;## kw_l_add
;kw_l_add, <a>, <b>, <dest>  - a + b
kw_l_add:
			pop hl
			pop de
			pop ix
			ld a, (de)
			add a, (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+3), a
			ret

ntc_rg301_e:
			IF ($ < 32768) && (ntc_rg302_e - ntc_rg302 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg302_e - ntc_rg302 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg302:
;## ntc_lmul ntc_ldata
; ntc_la * ntc_lb -> ntc_lr (low 32 bits, same signed / unsigned). jp (ix)
ntc_lmul:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_lm_loop:
			ld hl, ntc_lb+3
			srl (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			jr nc, ntc_lm_skip
			ld de, ntc_la
			ld hl, ntc_lr
			ld a, (de)
			add a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
ntc_lm_skip:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			djnz ntc_lm_loop
			jp (ix)

ntc_rg302_e:
			IF ($ < 32768) && (ntc_rg303_e - ntc_rg303 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg303_e - ntc_rg303 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg303:
;## kw_l_mul ntc_lmul ntc_ldata
;kw_l_mul, <a>, <b>, <dest>  - a * b
kw_l_mul:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			ld ix, ntc_lmu_back
			jp ntc_lmul
ntc_lmu_back:
			ld hl, ntc_lr
; copy the 4 bytes at HL to (ntc_ldst), then next keyword
ntc_lstore:
			ld de, (ntc_ldst)
			ldi
			ldi
			ldi
			ldi
			ret

ntc_rg303_e:
			IF ($ < 32768) && (ntc_rg304_e - ntc_rg304 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg304_e - ntc_rg304 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg304:
;## ntc_buf2k
ntc_buf	equ 36688		; Option Buffer: the buffer outside the program

ntc_rg304_e:
			IF ($ < 32768) && (ntc_rg305_e - ntc_rg305 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg305_e - ntc_rg305 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg305:
;## ntc_memcore ntc_data ntc_mem ntc_memcore2 ntc_plat_memtop @shared
; ------------------------------------------------------------
; ntc_memcore - the Memory class, the part every scheme shares. The scheme
; (Option Memory, else the platform's default) is the section ntc_mem -
; only the one chosen is in the library (@if:): CPCExpansion (16K pages
; through the #4000 window, up to 4MB) or Small (main RAM only, no paging).
; Each class method jumps to mem_go with HL = the routine: mem_go runs it
; on the real stack (call / push are fine there), interrupts on in normal
; mode (off in turbo), and stores its HL result at mem_res (mem_go4: a Long, high
; word in mem_hi; mem_go0: no store - the routine writes the result
; itself, or there is none). A routine that fails jumps to mem_err with
; HL = the status; mem_err puts back the page that was in the window
; and unwinds to mem_go.
; Far pointer = a Long: address, page (page 0 = plain memory).
; Heap: blocks from mem_hlo to mem_hhi (a D page, or Small's main RAM),
; each with a 2 byte header: length including the header (bits 0-14),
; bit 15 = in use. Free blocks are at most #4000 (joins stop there).
; The scheme supplies: mem_start (the first call), mem_sel (HL = page
; into the window), mem_chk (HL = a page number, else BadPage).
; ------------------------------------------------------------
MEM_WIN		equ #4000
MEM_BADPAGE	equ -2

mem_a1:			dw 0
mem_a2:			dw 0
mem_a3:			dw 0
mem_res:		dw 0
mem_hi:			dw 0
mem_sp:			dw 0
mem_esp:		dw 0
mem_six:		dw 0
mem_siy:		dw 0
mem_need:		dw 0
mem_max:		dw 0
mem_srca:		dw 0
mem_dsta:		dw 0
mem_srcp:		dw 0
mem_dstp:		dw 0
mem_left:		dw 0
mem_chunk:		dw 0
mem_cur:		dw 1			; the page in the window
mem_keep:		dw 1			; the page to put back
mem_hlo:		dw MEM_WIN		; the heap region mem_fit / mem_big work in
mem_hhi:		dw #8000
mem_store:		db 0
mem_init:		db 0			; 1 = the first call has been

; mem_go / mem_go4 / mem_go0 - HL = the routine (see above)
mem_go0:
			xor a
			jr mem_gostart
mem_go4:
			ld a, 4
			jr mem_gostart
mem_go:
			ld a, 2
mem_gostart:
			ld (mem_store), a
			ld (mem_sp), sp
			ld sp, (ntc_csp)
			ld (mem_six), ix
			ld (mem_siy), iy
			ld de, 0
			ld (mem_hi), de
			push hl
			call mem_start
			pop hl
			ld de, (mem_cur)
			ld (mem_keep), de
			ld a, (ntc_nmode)		; normal mode: interrupts in during the call (Ticks keep
			or a					; counting through a long Sort or Copy); turbo: off
			jr z, mem_gocall
			ei
mem_gocall:
			ld (mem_esp), sp
			call mem_jphl
mem_back:
			di
			ld ix, (mem_six)
			ld iy, (mem_siy)
			ld a, (mem_store)
			or a
			jr z, mem_gone
			ex de, hl
			ld hl, (mem_res)
			ld (hl), e
			inc hl
			ld (hl), d
			cp 4
			jr nz, mem_gone
			ld de, (mem_hi)
			inc hl
			ld (hl), e
			inc hl
			ld (hl), d
mem_gone:
			ld sp, (mem_sp)
			ret
mem_jphl:
			jp (hl)
mem_err:
			ld sp, (mem_esp)
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ld de, 0
			ld (mem_hi), de
			jr mem_back

mem_chk_bad:
			ld hl, MEM_BADPAGE
			jp mem_err

ntc_rg305_e:
			IF ($ < 32768) && (ntc_rg306_e - ntc_rg306 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg306_e - ntc_rg306 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg306:
;## ntc_memcore2 ntc_memcore @shared @far
; ntc_memcore2 - the rest of the shared part: far pointers, the heap, bytes
; and words. Runs on the real stack (through mem_go), so a keyword ROM set
; can place it in another ROM of the set (@far).

; mem_far - HL = a far pointer's address (Long: address, page): DE = the
; address, HL = the page (0 = plain memory). Page not 0: it must be a page
; this machine has and the address in the window, else mem_err BadPage.
mem_far:
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			or h
			ret z
			call mem_chk
			ld a, d
			and #C0
			cp #40
			jp nz, mem_chk_bad		; (jr: another part, maybe across Option Reserve)
			ret

; PageOf(ptr): a far pointer's page
mem_pageof:
			ld hl, (mem_a1)
			inc hl
			inc hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ret

; Address(ptr): its page into the window (page 0: nothing); the address
mem_address:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			call nz, mem_sel
			ex de, hl
			ret

; HeapStart(), HeapEnd(): the heap region (CPCExpansion: the window, a D page at a time)
mem_heapstart:
			ld hl, (mem_hlo)
			ret
mem_heapend:
			ld hl, (mem_hhi)
			ret
; ProgramStart(), ProgramEnd() (the first byte after the program and its
; arrays), Top() (the platform's top of free RAM), StackTop() (the real stack)
mem_progstart:
			ld hl, ntc_start
			ret
mem_progend:
			ld hl, ntc_free
			ret
mem_top:
			jp ntc_plat_memtop
mem_stacktop:
			ld hl, (ntc_csp)
			ret

; mem_atend - Z when HL = mem_hhi (the heap region's end). Keeps BC, DE, HL.
mem_atend:
			ld a, (mem_hhi)
			cp l
			ret nz
			ld a, (mem_hhi + 1)
			cp h
			ret
; mem_cap - HL = two joined blocks' length: NC = too long (over #4000), C = fine
mem_cap:
			ld a, h
			cp #40
			ret c
			scf
			ccf
			ret nz
			ld a, l
			cp 1					; #4000 exactly: C
			ret

; mem_fit - in the heap region (mem_hlo .. mem_hhi: a D page, or Small's main RAM): the first free block of mem_need
; bytes or more (free neighbours joined on the way), split when 4 or more
; bytes are left over, marked in use. Z: HL = its data. NZ: none.
mem_fit:
			ld hl, (mem_hlo)
mem_f_lp:
			call mem_atend
			jr z, mem_f_none
			ld e, (hl)
			inc hl
			ld d, (hl)
			dec hl
			bit 7, d
			jr z, mem_f_free
			res 7, d
mem_f_next:
			add hl, de
			jr mem_f_lp
mem_f_free:
			push hl
			add hl, de				; the block after
			call mem_atend
			jr z, mem_f_last
			ld c, (hl)
			inc hl
			ld b, (hl)
			bit 7, b
			jr nz, mem_f_last
			ld h, d					; free too: join them, up to #4000
			ld l, e
			add hl, bc
			call mem_cap
			jr nc, mem_f_last
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
			jr mem_f_free
mem_f_last:
			pop hl
			push hl
			ex de, hl				; HL = its length, DE = the block
			ld bc, (mem_need)
			or a
			sbc hl, bc				; what is left over
			jr c, mem_f_small
			ld a, h
			or a
			jr nz, mem_f_cut
			ld a, l
			cp 4
			jr nc, mem_f_cut
			add hl, bc				; all of it
			ld b, h
			ld c, l
			pop hl
			jr mem_f_take
mem_f_cut:
			ex de, hl				; DE = left over, HL = the block
			pop hl
			push hl
			add hl, bc				; the free block after it
			ld (hl), e
			inc hl
			ld (hl), d
			pop hl
mem_f_take:
			ld (hl), c
			inc hl
			ld a, b
			or #80
			ld (hl), a
			inc hl
			xor a
			ret
mem_f_small:
			add hl, bc				; HL = its length again
			ex de, hl
			pop hl
			jr mem_f_next
mem_f_none:
			or 1					; NZ
			ret

; mem_big - in the heap region: join free neighbours, mem_max =
; the biggest free block's length if bigger
mem_big:
			ld hl, (mem_hlo)
mem_b_lp:
			call mem_atend
			ret z
			ld e, (hl)
			inc hl
			ld d, (hl)
			dec hl
			bit 7, d
			jr z, mem_b_free
			res 7, d
mem_b_next:
			add hl, de
			jr mem_b_lp
mem_b_free:
			push hl
			add hl, de
			call mem_atend
			jr z, mem_b_end
			ld c, (hl)
			inc hl
			ld b, (hl)
			bit 7, b
			jr nz, mem_b_end
			ld h, d
			ld l, e
			add hl, bc
			call mem_cap
			jr nc, mem_b_end
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			dec hl
			jr mem_b_free
mem_b_end:
			pop hl
			push hl
			ld hl, (mem_max)
			or a
			sbc hl, de
			pop hl
			jr nc, mem_b_next
			ld (mem_max), de
			jr mem_b_next

; ---- single bytes and words through far pointers (the window is put back)

; mem_at - mem_a1 = a far pointer's address: its page in, HL = the address
mem_at:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			call nz, mem_sel
			ex de, hl
			ret

mem_readbyte:
			call mem_at
			ld l, (hl)
			ld h, 0
			jr mem_putback
mem_readword:
			call mem_at
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jr mem_putback
mem_writebyte:
			call mem_at
			ld a, (mem_a2)
			ld (hl), a
			jr mem_putback
mem_writeword:
			call mem_at
			ld de, (mem_a2)
			ld (hl), e
			inc hl
			ld (hl), d
mem_putback:
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ret

ntc_rg306_e:
			IF ($ < 32768) && (ntc_rg307_e - ntc_rg307 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg307_e - ntc_rg307 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg307:
;## ntc_mem ntc_memcore ntc_membank @shared @far
; ------------------------------------------------------------
; ntc_mem (CPCExpansion) - 16K RAM pages in the #4000-#7FFF window (CPC gate
; array RAM setting: C0 = plain, C4-C7 + bank * 8 = page 0-3 of a 64K bank;
; the port's high byte #7F .. #78 picks the 512K block), up to a 4MB
; expansion: 64 banks, 257 pages (NTC_MEMBANKS: Option Memory's limit).
;   Page 1  = main RAM #4000-#7FFF (setting #C0)
;   Page 2+ = 4 pages for each bank the probe finds, the standard 512K
;             (port #7F) first, then the blocks on #7E .. #78
;   Page numbers are 16 bit (a far pointer's high word); 0 = plain memory.
;   No pages at all when the program (ntc_start .. ntc_free) or the
;   real stack is in the window: switching would hide them.
; Tables, made by the first call (mem_start) from ntc_free up, sized to
; what the probe finds (3 bytes a page); fewer pages when there isn't room
; below #4000 (or below the real stack):
;   the port table - 2 bytes a page: the BC that selects it (out (c), c),
;                    so selecting a page is a look-up, nothing worked out
;   the RAT        - 1 byte a page, its type: - free, C, D, I, U, B (the 4
;                    pages of a whole bank, AllocBank)
; No lists: a free page or bank is found by scanning the RAT (CPIR), a page
; is freed by writing - back. C / I / U pages come from the low block first
; (main + the #7F block), D pages from the high one (#78-#7E); each falls
; back to the other. On 576K or less every page is low.
; The page in the window is kept in mem_cur, written before the port,
; so an interrupt handler can always put the right page back.
; A new D page is one free block of #4000.
; ------------------------------------------------------------
MEM_BANKS	equ NTC_MEMBANKS	; 0 - 64
MEM_LB		equ 6			; the whole-bank kind (mem_kinds)

mem_count:		dw 0			; pages (0 = no paging)
mem_tport:		dw 0			; the port table (2 bytes a page: its BC)
mem_ttype:		dw 0			; the RAT (1 byte a page: its type)
mem_tend:		dw 0			; the first byte after them
mem_fp:			dw 0			; (making the port table: the next bank found)
mem_banks:		db 0			; 64K banks found
mem_tl:			db 0
mem_sw:			db 0			; mem_scan: 0 low, 1 high, 2 any
mem_kinds:		db "--CDIUB"		; the type character of each kind (0, 1 free)
mem_found:		ds MEM_BANKS + 1	; probe: the banks found (0-63), in order
mem_save:		ds MEM_BANKS + 1	; probe: the bytes the markers replace
mem_bksp:		dw 0			; CallBank: the real stack while bank code runs
mem_bkrmr:		db 0			; and the ROM / mode byte to put back

; mem_start - the first call: can this program page, what is fitted, the tables
mem_start:
			ld a, (mem_init)
			or a
			ret nz
			inc a
			ld (mem_init), a
			ld hl, ntc_free
			ld (mem_tend), hl
	IF NTC_WINHOLE
			jr mem_st_prog			; the program is built round the window (Option Reserve)
	ENDIF
	IF NTC_ROMLIB					; the keyword ROM: free RAM from #8000 on = built round it
			ld a, h
			cp #80
			jr nc, mem_st_prog
	ENDIF
			ld de, MEM_WIN + 1		; the program must be out of the window:
			or a					; it ends by #4000 ...
			sbc hl, de
			jr c, mem_st_prog
			ld hl, ntc_start		; ... or starts at #8000 or above
			ld de, #8000
			or a
			sbc hl, de
			ret c
mem_st_prog:
			ld hl, (ntc_csp)		; and the real stack too: at or below #4000,
			ld de, MEM_WIN + 1		; or 64 bytes or more above #8000
			or a
			sbc hl, de
			jr c, mem_probe
			ld hl, (ntc_csp)
			ld de, #8040
			or a
			sbc hl, de
			ret c
; the probe: interrupts off, nothing written until every byte is saved.
; Markers go in bank 63 down to bank 0, then main RAM, so a bank the
; hardware doesn't decode (a 6128 has one bank, a 512K expansion ignores
; the port's block bits) reads back a lower bank's marker, and a 64K
; machine (C4-C7 do nothing) reads main RAM's.
mem_probe:
		IF MEM_BANKS > 0
			ld a, i					; P/V = interrupts were on
			di
			push af
			ld bc, #7FC0
			out (c), c
			ld a, (MEM_WIN)
			ld (mem_save + MEM_BANKS), a
			ld hl, mem_save
			ld e, 0
mem_pr_save:
			call mem_jbc
			out (c), c
			ld a, (MEM_WIN)
			ld (hl), a
			inc hl
			inc e
			ld a, e
			cp MEM_BANKS
			jr nz, mem_pr_save
			ld e, MEM_BANKS
mem_pr_mark:
			dec e
			call mem_jbc
			out (c), c
			ld a, e
			add a, #40
			ld (MEM_WIN), a
			ld a, e
			or a
			jr nz, mem_pr_mark
			ld bc, #7FC0
			out (c), c
			ld a, #A5
			ld (MEM_WIN), a
			ld hl, mem_found
			ld d, 0
			ld e, 0
mem_pr_read:
			call mem_jbc
			out (c), c
			ld a, e
			add a, #40
			push hl
			ld hl, MEM_WIN
			cp (hl)
			pop hl
			jr nz, mem_pr_none
			ld (hl), e				; this bank is there
			inc hl
			inc d
mem_pr_none:
			inc e
			ld a, e
			cp MEM_BANKS
			jr nz, mem_pr_read
			ld hl, mem_save + MEM_BANKS	; put the bytes back, bank 63 down to 0
			ld e, MEM_BANKS
mem_pr_back:
			dec e
			dec hl
			call mem_jbc
			out (c), c
			ld a, (hl)
			ld (MEM_WIN), a
			ld a, e
			or a
			jr nz, mem_pr_back
			ld bc, #7FC0
			out (c), c
			ld a, (mem_save + MEM_BANKS)
			ld (MEM_WIN), a
			ld a, d
			ld (mem_banks), a
			pop af
			jp po, mem_pr_di
			ei
mem_pr_di:
		ENDIF
			ld a, (mem_banks)		; pages = 1 + 4 a bank
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			inc hl
			ld (mem_count), hl
	IF NTC_WINHOLE
			call ntc_plat_memtop		; built round the window: the tables go above it
			jr mem_tb_lim			; (ntc_memtab), up to the platform's top
	ENDIF
	IF NTC_ROMLIB					; the keyword ROM: a program built round the window (it has no
			ld hl, ntc_free			; NTC_WINHOLE here) has its free RAM above it - up to the top
			ld a, h
			cp #80
			jr c, mem_tb_low
			call ntc_plat_memtop
			jr mem_tb_lim
mem_tb_low:
	ENDIF
			ld de, (ntc_csp)		; the tables must end by #4000, or 128 bytes
			ld hl, MEM_WIN			; under the real stack when it is lower
			or a
			sbc hl, de
			ld hl, MEM_WIN
			jr c, mem_tb_lim
			ld hl, -128
			add hl, de
mem_tb_lim:
			ld (mem_tend), hl		; the limit, for now
mem_tb_fit:
			ld hl, (mem_count)
			ld a, h
			or l
			jr z, mem_tb_none
			ld d, h
			ld e, l
			add hl, hl
			add hl, de				; 3 bytes a page
	IF NTC_WINHOLE
			ld de, ntc_memtab
	ELSE
			ld de, ntc_free
	ENDIF
			add hl, de
			ex de, hl				; DE = their end
			ld hl, (mem_tend)
			or a
			sbc hl, de
			jr nc, mem_tb_ok
			ld hl, (mem_count)		; no room: one page fewer
			dec hl
			ld (mem_count), hl
			jr mem_tb_fit
mem_tb_none:
	IF NTC_WINHOLE
			ld hl, ntc_memtab
	ELSE
			ld hl, ntc_free
	ENDIF
			ld (mem_tend), hl
			ret
mem_tb_ok:
			ld (mem_tend), de
	IF NTC_WINHOLE
			ld hl, ntc_memtab
	ELSE
			ld hl, ntc_free
	ENDIF
			ld (mem_tport), hl
			ld de, (mem_count)
			add hl, de
			add hl, de
			ld (mem_ttype), hl
			ld bc, (mem_count)		; the RAT: every page free
			ld (hl), '-'
			dec bc
			ld a, b
			or c
			jr z, mem_tb_ports
			ld d, h
			ld e, l
			inc de
			ldir
mem_tb_ports:						; the port table: page 1 main RAM, then 4 a bank found
			ld hl, (mem_tport)
			ld (hl), #C0
			inc hl
			ld (hl), #7F
			inc hl
			ld de, (mem_count)
			dec de					; DE = pages left
			ld bc, mem_found
			ld (mem_fp), bc
mem_tb_bk:
			ld a, d
			or e
			ret z
			push de
			ld bc, (mem_fp)
			ld a, (bc)
			inc bc
			ld (mem_fp), bc
			ld e, a
			call mem_jbc			; BC = its page 0's port (keeps DE, HL)
			pop de
			ld a, 4
mem_tb_pg:
			ld (hl), c
			inc hl
			ld (hl), b
			inc hl
			inc c
			dec de
			push af
			ld a, d
			or e
			jr z, mem_tb_pend		; (fewer pages than found: the rest left out)
			pop af
			dec a
			jr nz, mem_tb_pg
			jr mem_tb_bk
mem_tb_pend:
			pop af
			ret

; mem_jbc - E = bank 0-63: BC = the port for its page 0 (B = #7F - E / 8,
; C = #C4 + (E and 7) * 8). Keeps DE, HL.
mem_jbc:
			ld a, e
			rrca
			rrca
			rrca
			and 7
			ld b, a
			ld a, #7F
			sub b
			ld b, a
			ld a, e
			and 7
			add a, a
			add a, a
			add a, a
			add a, #C4
			ld c, a
			ret

; mem_sel - HL = page (valid): into the window. mem_cur first, then the
; port; nothing done when it is in already. Keeps BC, DE, HL.
mem_sel:
			push hl
			push de
			push bc
			ld de, (mem_cur)
			ld a, e
			cp l
			jr nz, mem_se_do
			ld a, d
			cp h
			jr z, mem_se_end
mem_se_do:
			ld (mem_cur), hl
			ld a, h
			or l
			ld bc, #7FC0			; (0: plain RAM)
			jr z, mem_se_out
			add hl, hl				; its port from the port table
			ld de, (mem_tport)
			add hl, de
			dec hl
			ld b, (hl)
			dec hl
			ld c, (hl)
mem_se_out:
			ld (ntc_rampt), bc
			out (c), c
mem_se_end:
			pop bc
			pop de
			pop hl
			ret

; mem_chk - HL = a page number: 1 .. mem_count, else mem_err BadPage.
; Keeps BC, DE, HL.
mem_chk:
			ld a, h
			or l
			jp z, mem_chk_bad
			push de
			push hl
			ex de, hl
			ld hl, (mem_count)
			or a
			sbc hl, de
			pop hl
			pop de
			ret nc
			jp mem_chk_bad
; ---- the tables (BC = a page)

; mem_tpb - HL = its type byte (in the RAT). Keeps A, BC, DE.
mem_tpb:
			ld hl, (mem_ttype)
			add hl, bc
			dec hl
			ret
; mem_push - A = a kind (mem_kinds: 2-6): the page is of that kind now. Keeps A, BC, DE.
mem_push:
			push af
			push de
			ld e, a
			ld d, 0
			ld hl, mem_kinds
			add hl, de
			ld a, (hl)
			call mem_tpb
			ld (hl), a
			pop de
			pop af
			ret
; mem_remove - (A = a kind) nothing to take it off: the RAT has no lists. NZ. Keeps BC, DE.
mem_remove:
			ld a, 1
			or a
			ret
; mem_lowhigh - A = the block the page is in: 0 low (main, or the #7F
; block) or 1 high. Keeps BC, DE.
mem_lowhigh:
			push de
			ld h, b
			ld l, c
			add hl, hl
			ld de, (mem_tport)
			add hl, de
			dec hl					; its port's high byte
			ld a, (hl)
			pop de
			cp #7F
			ld a, 0
			ret z
			inc a
			ret
; mem_tofree - the page free again. Keeps BC, DE.
mem_tofree:
			call mem_tpb
			ld (hl), '-'
			ret
; mem_scan - A = 0 low, 1 high, 2 either: BC = the first free page in it, NZ;
; Z = none
mem_scan:
			ld (mem_sw), a
			ld hl, (mem_ttype)
			ld bc, (mem_count)
mem_sc_lp:
			ld a, b
			or c
			ret z
			ld a, '-'
			cpir
			jr nz, mem_sc_none
			push bc
			push hl
			ld de, (mem_ttype)
			or a
			sbc hl, de				; the page: its entry is at HL - 1
			ld b, h
			ld c, l
			ld a, (mem_sw)
			cp 2
			jr z, mem_sc_hit
			call mem_lowhigh
			ld hl, mem_sw
			cp (hl)
			jr z, mem_sc_hit
			pop hl
			pop bc
			jr mem_sc_lp
mem_sc_hit:
			pop af
			pop af
			ld a, 1
			or a
			ret
mem_sc_none:
			xor a
			ret
; mem_dnext - BC = a page (0: before the first): BC = the next D page, NZ;
; Z = none
mem_dnext:
			ld hl, (mem_count)
			or a
			sbc hl, bc
			ret z
			push hl
			ld hl, (mem_ttype)
			add hl, bc
			pop bc
			ld a, 'D'
			cpir
			jr nz, mem_sc_none
			ld de, (mem_ttype)
			or a
			sbc hl, de
			ld b, h
			ld c, l
			ld a, 1
			or a
			ret
; mem_listof - A = the page's kind (2-6), or its free block (0, 1). Keeps BC, DE.
mem_listof:
			call mem_tpb
			ld a, (hl)
			push bc
			ld hl, mem_kinds + 2
			ld b, 5
			ld c, 2
mem_lo_lp:
			cp (hl)
			jr z, mem_lo_got
			inc hl
			inc c
			djnz mem_lo_lp
			pop bc
			jp mem_lowhigh
mem_lo_got:
			ld a, c
			pop bc
			ret
; mem_kindlist - A = a type character: A = its kind (2-5), NZ; Z = not one.
mem_kindlist:
			ld hl, mem_kinds + 2
			ld b, 4
			ld c, 2
mem_kl_lp:
			cp (hl)
			jr z, mem_kl_got
			inc hl
			inc c
			djnz mem_kl_lp
			xor a
			ret
mem_kl_got:
			ld a, c
			or a
			ret
; mem_take - A = a kind (2-5): a free page of that kind now - D from the
; high block first, the others from the low one - a D page made one free
; block. BC = the page, NZ; Z = none left.
mem_take:
			ld (mem_tl), a
			cp 3
			ld a, 1
			jr z, mem_tk_s
			xor a
mem_tk_s:
			call mem_scan
			jr nz, mem_tk_got
			ld a, 2
			call mem_scan
			ret z
mem_tk_got:
			ld a, (mem_tl)
			call mem_push
			cp 3
			jr nz, mem_tk_done
			ld h, b
			ld l, c
			call mem_sel
			ld hl, #4000
			ld (MEM_WIN), hl
			ld hl, (mem_keep)
			call mem_sel
mem_tk_done:
			ld a, 1
			or a
			ret

; ---- what's there

; Pages(): pages (0 = no paging, 1 = 64K, 5 = 128K ... 33 = 512K ... 257 = 4MB)
mem_pages:
			ld hl, (mem_count)
			ret

; FreePages(): the free pages (- in the RAT)
mem_freepages:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
			ld b, h
			ld c, l
			ld hl, (mem_ttype)
			ld de, 0
mem_fp_lp:
			ld a, '-'
			cpir
			jr nz, mem_fp_end
			inc de
			ld a, b
			or c
			jr nz, mem_fp_lp
mem_fp_end:
			ex de, hl
			ret

; RamSize(): K of RAM the probe found (64 + 64 a bank), 0 = not probed
mem_ramsize:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
			ld a, (mem_banks)
			ld l, a
			ld h, 0
			inc hl
			add hl, hl				; x 64
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			ret

; Model(): 0 none, 1 small (1 page), 2 medium (up to 5), 3 large (up to
; 33, a 512K expansion), 4 huge (more)
mem_model:
			ld de, (mem_count)
			ld hl, 0
			ld a, d
			or a
			jr nz, mem_md_huge
			ld a, e
			or a
			ret z
			inc l
			cp 2
			ret c
			inc l
			cp 6
			ret c
			inc l
			cp 34
			ret c
mem_md_huge:
			ld l, 4
			ret

; TableEnd(): the first byte after Memory's tables (they start at the program's end)
mem_tableend:
			ld hl, (mem_tend)
			ret

; PageType(page): its type character
mem_pagetype:
			ld hl, (mem_a1)
			call mem_chk
			ld b, h
			ld c, l
			call mem_tpb
			ld l, (hl)
			ld h, 0
			ret

; Map(first, count): one character per page from first, into the string
; result (as many as fit; pages past the last are left out)
mem_map:
			ld hl, (mem_res)
			dec hl
			ld a, (hl)				; the string's capacity
			inc hl
			ld (mem_srca), hl
			ld (mem_chunk), a
			ld bc, (mem_a1)
			ld hl, (mem_a2)
			ld (mem_left), hl
mem_mp_lp:
			ld hl, (mem_left)
			bit 7, h
			jr nz, mem_mp_end
			ld a, h
			or l
			jr z, mem_mp_end
			ld a, b
			or c
			jr z, mem_mp_end
			ld hl, (mem_count)
			or a
			sbc hl, bc
			jr c, mem_mp_end
			ld a, (mem_chunk)
			or a
			jr z, mem_mp_end
			dec a
			ld (mem_chunk), a
			call mem_tpb
			ld a, (hl)
			ld hl, (mem_srca)
			ld (hl), a
			inc hl
			ld (mem_srca), hl
			inc bc
			ld hl, (mem_left)
			dec hl
			ld (mem_left), hl
			jr mem_mp_lp
mem_mp_end:
			ld hl, (mem_srca)
			ld (hl), 0
			ret

; ---- whole pages

; AllocPage(kind): a free page, now of that kind (C, D, I, U); 0 = none left
mem_allocpage:
			ld hl, (mem_count)
			ld a, h
			or l
			jr z, mem_ap_none
			ld hl, (mem_a1)
			ld a, h
			or a
			jr nz, mem_ap_none
			ld a, l
			call mem_kindlist
			jr z, mem_ap_none
			call mem_take
			jr z, mem_ap_none
			ld h, b
			ld l, c
			ret
mem_ap_none:
			ld hl, 0
			ret

; FreePage(page): back to free (a D page's blocks go with it). OK, or
; BadPage (not a page, or free already)
mem_freepage:
			ld hl, (mem_a1)
			call mem_chk
			ld b, h
			ld c, l
			call mem_listof
			cp 2
			jp c, mem_chk_bad
			call mem_remove
			call mem_tofree
			ld hl, 0
			ret

; SelectPage(page): into the window; #4000
mem_selpage:
			ld hl, (mem_a1)
			call mem_chk
			call mem_sel
			ld hl, MEM_WIN
			ret

; CurrentPage(): the page in the window (0 = no paging)
mem_curpage:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
			ld hl, (mem_cur)
			ret

; ---- whole 64K banks (page numbers 4 * bank - 2 .. 4 * bank + 1)

; Banks(): whole banks the tables cover (0 = none)
mem_bankcount:
			ld hl, (mem_count)
			ld a, h
			or l
			ret z
			dec hl
			srl h
			rr l
			srl h
			rr l
			ret

; mem_bkfirst - (mem_a1) = a bank, 1 .. Banks(): BC = its first page, else
; mem_err BadPage
mem_bkfirst:
			call mem_bankcount
			ld de, (mem_a1)
			ld a, d
			or e
			jp z, mem_chk_bad
			or a
			sbc hl, de
			jp c, mem_chk_bad
			ex de, hl
			dec hl
			add hl, hl
			add hl, hl
			inc hl
			inc hl
			ld b, h
			ld c, l
			ret

; AllocBank(): a bank whose 4 pages are all free, now type B; 0 = none
mem_allocbank:
			call mem_bankcount
			ld a, l
			or a
			jr z, mem_ab_none
			ld (mem_tl), a			; banks left to try
			ld bc, 2
mem_ab_lp:
			push bc
			ld d, 4
mem_ab_chk:
			call mem_listof
			cp 2
			jr nc, mem_ab_used
			inc bc
			dec d
			jr nz, mem_ab_chk
			pop bc					; all 4 free: onto the bank list
			push bc
			ld d, 4
mem_ab_take:
			call mem_listof
			call mem_remove
			ld a, MEM_LB
			call mem_push
			inc bc
			dec d
			jr nz, mem_ab_take
			pop hl					; bank = (first page + 2) / 4
			inc hl
			inc hl
			srl h
			rr l
			srl h
			rr l
			ret
mem_ab_used:
			pop bc
			ld hl, 4
			add hl, bc
			ld b, h
			ld c, l
			ld a, (mem_tl)
			dec a
			ld (mem_tl), a
			jr nz, mem_ab_lp
mem_ab_none:
			ld hl, 0
			ret

; FreeBank(bank): its 4 pages back to free. OK, or BadPage (not a bank,
; or not taken with AllocBank)
mem_bkstub:
			ld hl, ntc_bk_stub
			ret

mem_freebank:
			call mem_bkfirst
			push bc
			ld d, 4
mem_fb_chk:
			call mem_listof
			cp MEM_LB
			jp nz, mem_chk_bad
			inc bc
			dec d
			jr nz, mem_fb_chk
			pop bc
			ld d, 4
mem_fb_lp:
			ld a, MEM_LB
			call mem_remove
			call mem_tofree
			inc bc
			dec d
			jr nz, mem_fb_lp
			ld hl, 0
			ret

; CallBank(bank, address, value): runs the bank's code at address with the
; whole 64K being that bank (RAM setting C2), HL = value; its HL comes back.
; The bank must be taken (AllocBank). The switch code (ntc_bk_stub, about
; 20 bytes) is copied into the bank at its own address first, so those
; bytes of the bank are overwritten. Interrupts are off and both ROMs are
; off while the bank code runs; it starts with the stack at the bank's top
; (#FFFF down) and ends with ret. It must keep the alternate registers.
mem_callbank:
			call mem_bkfirst
			call mem_listof
			cp MEM_LB
			jp nz, mem_chk_bad
			ld hl, ntc_bk_stub		; copy the switch code into the bank
mem_cb_cp:
			push bc
			ld a, h					; its page in the bank: address / #4000
			rlca
			rlca
			and 3
			add a, c
			ld c, a
			jr nc, mem_cb_nc
			inc b
mem_cb_nc:
			push hl
			ld h, b
			ld l, c
			call mem_sel
			pop hl
			ld b, (hl)
			ld a, h
			and #3F
			or #40
			ld d, a
			ld e, l
			ld a, b
			ld (de), a
			pop bc
			inc hl
			ld a, l
			cp low ntc_bk_end
			jr nz, mem_cb_cp
			ld a, h
			cp high ntc_bk_end
			jr nz, mem_cb_cp
			ld hl, (mem_keep)
			call mem_sel
			call mem_bkfirst		; BC = C2 for the bank: its page 0's port
			ld h, b					; ((#C4 + bank bits) and #F8, or 2)
			ld l, c
			add hl, hl
			ld de, (mem_tport)
			add hl, de
			dec hl
			ld b, (hl)
			dec hl
			ld a, (hl)
			and #F8
			or 2
			ld c, a
			ld de, (mem_a2)
			ld hl, (mem_a3)
			jp ntc_bk_go

; ---- heap in D pages

; Alloc(size): a far pointer to size bytes in a D page, 0 = no room.
; Tries the page in the window, then the other D pages, then takes a free
; page. The window is left as it was.
mem_alloc:
			ld hl, (mem_count)
			ld a, h
			or l
			jr z, mem_al_fail
			ld hl, (mem_a1)
			ld a, h
			or l
			jr nz, mem_al_size
			inc hl
mem_al_size:
			ld de, #3FFF			; up to #3FFE: a page less its header
			or a
			push hl
			sbc hl, de
			pop hl
			jr nc, mem_al_fail
			inc hl
			inc hl
			ld (mem_need), hl
			ld bc, (mem_keep)
			call mem_tpb
			ld a, (hl)
			cp 'D'
			jr nz, mem_al_scan
			ld h, b
			ld l, c
			call mem_try
			jr z, mem_al_got
mem_al_scan:
			ld bc, 0
mem_al_lp:
			call mem_dnext
			jr z, mem_al_new
			ld hl, (mem_keep)
			or a
			sbc hl, bc
			jr z, mem_al_lp
			push bc
			ld h, b
			ld l, c
			call mem_try
			pop bc
			jr z, mem_al_got
			jr mem_al_lp
mem_al_new:
			ld a, 3
			call mem_take
			jr z, mem_al_back
			ld h, b
			ld l, c
			call mem_try
mem_al_got:
			ld de, (mem_cur)		; HL = the data, its page is in
			ld (mem_hi), de
			push hl
			ld hl, (mem_keep)
			call mem_sel
			pop hl
			ret
mem_al_back:
			ld hl, (mem_keep)
			call mem_sel
mem_al_fail:
			ld hl, 0
			ld (mem_hi), hl
			ret

; mem_try - HL = a D page: select it, then mem_fit
mem_try:
			call mem_sel
			jp mem_fit

; Free(ptr): a block Alloc gave back. A page with nothing left in use
; goes back to free. OK, or BadPage (not a block in use in a D page)
mem_free:
			ld hl, (mem_a1)
			call mem_far
			ld a, h
			or l
			jp z, mem_chk_bad
			ld b, h
			ld c, l
			call mem_tpb
			ld a, (hl)
			cp 'D'
			jp nz, mem_chk_bad
			ld h, b
			ld l, c
			call mem_sel
			ex de, hl
			dec hl
			bit 7, (hl)
			jr z, mem_err_page
			res 7, (hl)
			ld hl, #4000			; is the whole page free now?
			ld (mem_need), hl
			push bc
			call mem_fit			; only a page with every block free fits
			pop bc
			jr nz, mem_fr_done
			ld a, 3
			call mem_remove
			call mem_tofree
mem_fr_done:
			ld hl, (mem_keep)
			call mem_sel
			ld hl, 0
			ret
mem_err_page:
			ld hl, (mem_keep)
			call mem_sel
			jp mem_chk_bad

; Largest(): the biggest block Alloc could give now
mem_largest:
			ld hl, 0
			ld (mem_max), hl
			call mem_freepages		; a free page: a whole page
			ld a, h
			or l
			ld hl, #3FFE
			ret nz
			ld bc, 0
mem_lg_lp:
			call mem_dnext
			jr z, mem_lg_end
			ld h, b
			ld l, c
			call mem_sel
			push bc
			call mem_big
			pop bc
			jr mem_lg_lp
mem_lg_end:
			ld hl, (mem_keep)
			call mem_sel
			ld hl, (mem_max)
			ld a, h
			or l
			ret z
			dec hl
			dec hl
			ret

ntc_rg307_e:
			IF ($ < 32768) && (ntc_rg308_e - ntc_rg308 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg308_e - ntc_rg308 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg308:
;## ntc_membank ntc_plat_rmr @shared @romram
; ------------------------------------------------------------
; ntc_membank - Memory's CallBank switch (CPCExpansion). Runs from RAM
; (a keyword ROM can't be seen once both ROMs are off). BC = the C2
; setting and port for the bank, DE = the address in the bank, HL = value.
; ntc_bk_stub .. ntc_bk_end is also copied into the bank at the same
; address: each out is followed by the next byte from the other 64K.
; ------------------------------------------------------------
ntc_bk_go:
			ld a, i					; P/V = interrupts were on
			di
			push af
			ld (mem_bksp), sp
			call ntc_plat_rmr
			ld (mem_bkrmr), a
			or #0C					; both ROMs off
			push bc
			ld b, #7F
			out (c), a
			pop bc
ntc_bk_stub:
			out (c), c				; the bank is all 64K now
			ld sp, 0
			ld bc, ntc_bk_ret
			push bc
			push de
			ret						; to the bank's code, HL = value
ntc_bk_ret:
			ld bc, #7FC0
			out (c), c				; main RAM again
ntc_bk_end:
			ld sp, (mem_bksp)
			ld a, (mem_bkrmr)
			ld b, #7F
			out (c), a				; the ROMs as they were
			ld bc, (ntc_rampt)
			out (c), c				; and the window's page
			pop af
			jp po, ntc_bk_di
			ei
ntc_bk_di:
			ret

ntc_rg308_e:
			IF ($ < 32768) && (ntc_rg309_e - ntc_rg309 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg309_e - ntc_rg309 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg309:
;## ntc_keys ntc_data @shared
; ------------------------------------------------------------
; ntc_keys - the Keys class (CPC): the keyboard matrix read straight from the
; hardware (PSG register 14 through the PPI), all 10 lines each time, so it
; works with or without the firmware, in turbo and normal mode. Entered
; with jp from a method, with the method's result pointer still on the
; thread: the result goes there and ret carries on. No stack used.
;   ntc_kdown - HL = a key number 0-79 (the CPC's, as INKEY(n)): -1 held, 0 not
;   ntc_kjoy  - HL = joystick 0 / 1: bits up 1, down 2, left 4, right 8,
;               fire 2 16, fire 1 32 (as JOY(n))
; ------------------------------------------------------------
ntc_kmat:		ds 10			; the matrix (0 = pressed)
ntc_karg:		db 0
ntc_kwhat:		db 0

ntc_kdown:
			ld a, h
			or a
			jr nz, ntc_kd_no
			ld a, l
			cp 80
			jr nc, ntc_kd_no
			ld (ntc_karg), a
			xor a
			jr ntc_kscan
ntc_kjoy:
			ld a, l
			and 1
			ld (ntc_karg), a
			ld a, 1
ntc_kscan:
			ld (ntc_kwhat), a
			ld bc, #F40E		; PSG register 14
			out (c), c
			ld bc, #F6C0		; PSG: select register
			out (c), c
			ld bc, #F600		; PSG: inactive
			out (c), c
			ld bc, #F792		; PPI port A input
			out (c), c
			ld hl, ntc_kmat
			ld a, #40			; PSG read + line 0
ntc_ksc_line:
			ld b, #F6
			out (c), a
			ld b, #F4
			in d, (c)
			ld (hl), d
			inc hl
			inc a
			cp #4A
			jr nz, ntc_ksc_line
			ld bc, #F782		; PPI port A output
			out (c), c
			ld bc, #F600
			out (c), c
			ld a, (ntc_kwhat)
			or a
			jr nz, ntc_kj_got
			ld a, (ntc_karg)	; line = n / 8, bit = n and 7
			ld c, a
			rrca
			rrca
			rrca
			and 31
			ld e, a
			ld d, 0
			ld hl, ntc_kmat
			add hl, de
			ld a, c
			and 7
			ld b, a
			inc b
			ld a, (hl)
ntc_kd_rot:
			rrca
			djnz ntc_kd_rot
			ld de, 0
			jr c, ntc_k_set		; 1 = not pressed
			dec de
			jr ntc_k_set
ntc_kd_no:
			ld de, 0
			jr ntc_k_set
ntc_kj_got:
			ld a, (ntc_karg)	; joystick 0 = line 9, 1 = line 6
			ld hl, ntc_kmat + 9
			or a
			jr z, ntc_kj_line
			ld hl, ntc_kmat + 6
ntc_kj_line:
			ld a, (hl)
			cpl
			and #3F
			ld e, a
			ld d, 0
ntc_k_set:
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

ntc_rg309_e:
			IF ($ < 32768) && (ntc_rg310_e - ntc_rg310 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg310_e - ntc_rg310 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg310:
;## ntc_romdisc ntc_data ntc_plat_romsel @shared @ramonly
; ------------------------------------------------------------
; ntc_romdisc - ROMDISC: read-only files kept in ROMs, the FileSystem's
; volume R (cpc, cpcmin, cpcfw). A disc is a set of ROMs NTCDISC.ROM,
; NTCDISC2.ROM ... (made by ntcRomDisc in ntc_compiler.js) in any slots
; 0-31: background ROMs whose names are followed by the block
;   "NTC", 2, "ROMDISC", 0, dw stamp, db place, db ROMs, dw directory (ROM 0)
; ROM 0 has the directory at #C040: entries of RD_ENTRY bytes, read until
; one whose flags have bit 7 set (the end):
;   +0 name (8, spaces after), +8 extension (3), +11 flags (bit 0
;   compressed - none are yet), +12 its ROM (place in the set), +13 its
;   address (dw), +15 its length (3 bytes)
; A file's bytes run on from its address; past #FFFF they go on at RD_DATA
; of the next ROM. Reading selects the disc's ROM (ntc_plat_romsel: rd_sel /
; rd_unsel), so this runs from RAM: it is not in the keyword ROM (@ramonly).
; Routines run on the real stack (rd_go on cpc, the FileSystem's fs_go on
; cpcmin / cpcfw); arguments in rd_a1 .. rd_a3, a string / Long result at
; (rd_res); HL = the result or a status. One file open: handle 2.
; ------------------------------------------------------------
RD_DATA		equ #C040		; directory (ROM 0) and file data start
RD_ENTRY	equ 18
RD_HANDLE	equ 2
RD_NOTSUP	equ -1
RD_NOTFOUND	equ -2
RD_BADNAME	equ -4
RD_NOHANDLE	equ -5
RD_BADHANDLE	equ -6
RD_EOF		equ -7
RD_TOOBIG	equ -8
rd_a1:			dw 0
rd_a2:			dw 0
rd_a3:			dw 0
rd_res:			dw 0
rd_sp:			dw 0
rd_six:			dw 0
rd_siy:			dw 0
rd_nostore:		db 0
rd_state:		db 0			; 0 = not looked for yet, 1 = there, 2 = none
rd_want:		db 0
rd_n:			db 0			; ROMs in the disc
rd_stamp:		dw 0
rd_dir:			dw 0			; the directory (ROM 0)
rd_slots:		ds 8			; each ROM's slot
rd_name:		ds 11			; a name as the directory has it
rd_ent:			ds RD_ENTRY		; the entry found
rd_isopen:		db 0			; 1 = a file open (handle 2)
rd_rom:			db 0			; reading: the ROM, the address, the bytes left
rd_addr:		dw 0
rd_left:		ds 3
rd_cnt:			dw 0
rd_dst:			dw 0
rd_cap:			db 0
rd_sig:			db "NTC", 2, "ROMDISC", 0
rd_sige:

; rd_go / rd_go0 - (cpc) HL = the routine: run on the real stack, its HL
; stored at (rd_res) (rd_go0: not stored - the routine writes its result)
rd_go0:
			ld a, 1
			jr rd_gostart
rd_go:
			xor a
rd_gostart:
			ld (rd_nostore), a
			ld (rd_sp), sp
			ld sp, (ntc_csp)
			ld (rd_six), ix
			ld (rd_siy), iy
			ld a, (ntc_nmode)
			or a
			jr z, rd_g_call
			ei
rd_g_call:
			call rd_jphl
			di
			ld ix, (rd_six)
			ld iy, (rd_siy)
			ld a, (rd_nostore)
			or a
			jr nz, rd_g_end
			ex de, hl
			ld hl, (rd_res)
			ld (hl), e
			inc hl
			ld (hl), d
rd_g_end:
			ld sp, (rd_sp)
			ret
rd_jphl:
			jp (hl)

; rd_mount - is a disc there? (looked for once). Z = yes
rd_mount:
			ld a, (rd_state)
			cp 1
			ret z
			or a
			jr nz, rd_mt_no
			xor a
			ld (rd_want), a
			call rd_scan
			jr c, rd_mt_none
			ld (rd_slots), a
			ld a, 1
rd_mt_more:
			ld (rd_want), a
			ld hl, rd_n
			cp (hl)
			jr nc, rd_mt_ok
			call rd_scan
			jr c, rd_mt_none		; a part missing: no disc
			ld b, a
			ld a, (rd_want)
			ld e, a
			ld d, 0
			ld hl, rd_slots
			add hl, de
			ld (hl), b
			inc a
			jr rd_mt_more
rd_mt_ok:
			ld a, 1
			ld (rd_state), a
			cp a					; Z
			ret
rd_mt_none:
			ld a, 2
			ld (rd_state), a
rd_mt_no:
			or 1					; NZ
			ret

; rd_scan - the disc ROM rd_want (0: any stamp; the others: ROM 0's stamp).
; NC: A = its slot (ROM 0: rd_n, rd_stamp, rd_dir set). C: not there
rd_scan:
			ld c, 0
rd_sc_next:
			push bc
			ld a, c
			call rd_sel
			call rd_sc_try
			call rd_unsel
			pop bc
			jr nc, rd_sc_got
			inc c
			ld a, c
			cp 32
			jr c, rd_sc_next
			scf
			ret
rd_sc_got:
			ld a, c
			ret
rd_sc_try:							; (the ROM is in) NC = it is the one
			ld a, (#C000)
			cp 1					; a background ROM
			jr nz, rd_sc_not
			ld hl, (#C004)			; its names
			ld a, h
			cp #C0
			jr c, rd_sc_not
rd_sc_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, rd_sc_name
			ld de, rd_sig
			ld b, rd_sige - rd_sig
rd_sc_cmp:
			ld a, (de)
			cp (hl)
			jr nz, rd_sc_not
			inc de
			inc hl
			djnz rd_sc_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)				; DE = its stamp
			inc hl
			ld a, (rd_want)
			cp (hl)
			jr nz, rd_sc_not
			inc hl
			or a
			jr nz, rd_sc_stamp
			ld (rd_stamp), de		; ROM 0: the disc's stamp, ROMs, directory
			ld a, (hl)
			ld (rd_n), a
			inc hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (rd_dir), de
			or a
			ret
rd_sc_stamp:
			ld hl, (rd_stamp)
			or a
			sbc hl, de
			ret z					; (NC)
rd_sc_not:
			scf
			ret

; rd_mkname - HL = a name ("NAME.EXT", "R:NAME.EXT"): rd_name. NC, or C = not
; a name (empty, more than 8.3)
rd_mkname:
			push hl
			ld hl, rd_name
			ld b, 11
rd_mk_sp:
			ld (hl), ' '
			inc hl
			djnz rd_mk_sp
			pop hl
			inc hl
			ld a, (hl)
			dec hl
			cp ':'
			jr nz, rd_mk_go
			inc hl					; past "R:"
			inc hl
rd_mk_go:
			ld de, rd_name
			ld b, 9					; up to 8 letters, then . or the end
			ld a, (hl)
			or a
			jr z, rd_mk_bad
rd_mk_lp:
			ld a, (hl)
			or a
			ret z					; (NC)
			inc hl
			cp '.'
			jr z, rd_mk_ext
			dec b
			jr z, rd_mk_bad
			call rd_up
			ld (de), a
			inc de
			jr rd_mk_lp
rd_mk_ext:
			ld de, rd_name + 8
			ld b, 4
rd_mk_elp:
			ld a, (hl)
			or a
			ret z
			inc hl
			dec b
			jr z, rd_mk_bad
			cp '.'
			jr z, rd_mk_bad
			call rd_up
			ld (de), a
			inc de
			jr rd_mk_elp
rd_mk_bad:
			scf
			ret
rd_up:
			cp 'a'
			ret c
			cp 'z' + 1
			ret nc
			sub 32
			ret

; rd_find - rd_a1 = a name: its entry into rd_ent. NC, or C with HL = the status
rd_find:
			call rd_mount
			ld hl, RD_NOTFOUND
			scf
			ret nz
			ld hl, (rd_a1)
			call rd_mkname
			ld hl, RD_BADNAME
			ret c
			ld a, (rd_slots)
			call rd_sel
			ld hl, (rd_dir)
rd_fd_lp:
			push hl
			ld de, 11
			add hl, de
			bit 7, (hl)				; the end
			pop hl
			jr nz, rd_fd_none
			push hl
			ld de, rd_name
			ld b, 11
rd_fd_cmp:
			ld a, (de)
			cp (hl)
			jr nz, rd_fd_nx
			inc de
			inc hl
			djnz rd_fd_cmp
			pop hl
			ld de, rd_ent
			ld bc, RD_ENTRY
			ldir
			call rd_unsel
			or a					; NC
			ret
rd_fd_nx:
			pop hl
			ld de, RD_ENTRY
			add hl, de
			jr rd_fd_lp
rd_fd_none:
			call rd_unsel
			ld hl, RD_NOTFOUND
			scf
			ret

; rd_start - reading from the start of rd_ent's file (rd_rom, rd_addr, rd_left)
rd_start:
			ld hl, rd_ent + 12
			ld de, rd_rom
			ld bc, 6
			ldir
			ret

; rd_copy - BC bytes (no more than are left) to DE: on from rd_rom / rd_addr
rd_copy:
			ld (rd_cnt), bc
			ld (rd_dst), de
rd_cp_lp:
			ld hl, (rd_cnt)
			ld a, h
			or l
			ret z
			ld hl, (rd_addr)		; this ROM's part: up to #FFFF
			ex de, hl
			ld hl, 0
			or a
			sbc hl, de				; HL = #10000 - address
			ld de, (rd_cnt)
			or a
			sbc hl, de
			jr nc, rd_cp_all
			add hl, de				; (only what this ROM has)
			ld b, h
			ld c, l
			jr rd_cp_do
rd_cp_all:
			ld b, d
			ld c, e
rd_cp_do:
			push bc
			call rd_romslot
			call rd_sel
			pop bc
			push bc
			ld hl, (rd_addr)
			ld de, (rd_dst)
			ldir
			ld (rd_dst), de
			call rd_unsel
			pop bc
			ld hl, (rd_cnt)
			or a
			sbc hl, bc
			ld (rd_cnt), hl
			call rd_adv
			jr rd_cp_lp

; rd_adv - BC bytes read: on in the file (the next ROM past #FFFF), fewer left
rd_adv:
			ld hl, (rd_addr)
			add hl, bc
			jr nc, rd_av_same
			ld a, h
			or l
			jr nz, rd_av_same
			ld hl, rd_rom
			inc (hl)
			ld hl, RD_DATA
rd_av_same:
			ld (rd_addr), hl
			ld hl, (rd_left)
			or a
			sbc hl, bc
			ld (rd_left), hl
			ret nc
			ld hl, rd_left + 2
			dec (hl)
			ret

; rd_romslot - A = the slot of rd_rom
rd_romslot:
			ld a, (rd_rom)
			ld e, a
			ld d, 0
			ld hl, rd_slots
			add hl, de
			ld a, (hl)
			ret

; rd_getb - the next byte of the open file: A, NC; C = the end
rd_getb:
			ld hl, (rd_left)
			ld a, h
			or l
			ld hl, rd_left + 2
			or (hl)
			scf
			ret z
			call rd_romslot
			call rd_sel
			ld hl, (rd_addr)
			ld a, (hl)
			push af
			call rd_unsel
			ld bc, 1
			call rd_adv
			pop af
			or a					; NC
			ret

; rd_hchk - rd_a1 must be handle 2, open: else (from the routine) BadHandle
rd_hchk:
			ld hl, (rd_a1)
			ld de, -RD_HANDLE
			add hl, de
			ld a, h
			or l
			jr nz, rd_hc_bad
			ld a, (rd_isopen)
			or a
			ret nz
rd_hc_bad:
			pop hl					; (out of the routine)
			ld hl, RD_BADHANDLE
			ret

; Load(name, addr, maxlen): its length, or a status (TooBig: nothing loaded)
rd_load:
			call rd_find
			ret c
			ld a, (rd_ent + 17)		; more than 65535, or more than maxlen
			or a
			ld hl, RD_TOOBIG
			ret nz
			ld de, (rd_ent + 15)
			ld hl, (rd_a3)
			or a
			sbc hl, de
			ld hl, RD_TOOBIG
			ret c
			call rd_start
			ld bc, (rd_ent + 15)
			ld de, (rd_a2)
			call rd_copy
			ld hl, (rd_ent + 15)
			ret

; Open(name, mode): handle 2, or a status (only ForRead: the disc is read only)
rd_open:
			ld a, (rd_isopen)
			or a
			ld hl, RD_NOHANDLE
			ret nz
			ld hl, (rd_a2)
			ld a, l
			cp 4				; ForReadRaw: the same (a ROMDISC file is read to its length)
			jr nz, rd_op_m
			ld l, 1
rd_op_m:
			dec hl
			ld a, h
			or l
			ld hl, RD_NOTSUP
			ret nz
			call rd_find
			ret c
			call rd_start
			ld a, 1
			ld (rd_isopen), a
			ld hl, RD_HANDLE
			ret

; Close(h): OK or BadHandle
rd_close:
			call rd_hchk
			xor a
			ld (rd_isopen), a
			ld hl, 0
			ret

; ReadByte(h): 0-255, EndOfFile, BadHandle
rd_readb:
			call rd_hchk
			call rd_getb
			ld hl, RD_EOF
			ret c
			ld l, a
			ld h, 0
			ret

; Read(h, addr, count): bytes read (fewer at the end)
rd_read:
			call rd_hchk
			ld hl, (rd_a3)
			bit 7, h
			jr z, rd_rd_pos
			ld hl, 0
rd_rd_pos:
			ld a, (rd_left + 2)		; no more than are left
			or a
			jr nz, rd_rd_go
			ld de, (rd_left)
			push hl
			or a
			sbc hl, de
			pop hl
			jr c, rd_rd_go
			ex de, hl
rd_rd_go:
			push hl
			ld b, h
			ld c, l
			ld de, (rd_a2)
			call rd_copy
			pop hl
			ret

; Eof(h): True when nothing is left (or h is not the open file)
rd_eof:
			ld hl, (rd_a1)
			ld de, -RD_HANDLE
			add hl, de
			ld a, h
			or l
			jr nz, rd_ef_yes
			ld a, (rd_isopen)
			or a
			jr z, rd_ef_yes
			ld hl, (rd_left)
			ld a, h
			or l
			ld hl, rd_left + 2
			or (hl)
			ld hl, 0
			ret nz
rd_ef_yes:
			ld hl, -1
			ret

; ReadLine(h): the next line (up to LF; CR dropped) into the string at (rd_res)
rd_readln:
			ld hl, (rd_res)
			ld (hl), 0
			dec hl
			ld a, (hl)
			ld (rd_cap), a
			inc hl
			ld (rd_dst), hl
			call rd_hchk
rd_rl_lp:
			call rd_getb
			jr c, rd_rl_end
			cp 10
			jr z, rd_rl_end
			cp 13
			jr z, rd_rl_lp
			ld c, a
			ld a, (rd_cap)
			or a
			jr z, rd_rl_lp			; full: the rest of the line is dropped
			dec a
			ld (rd_cap), a
			ld hl, (rd_dst)
			ld (hl), c
			inc hl
			ld (rd_dst), hl
			jr rd_rl_lp
rd_rl_end:
			ld hl, (rd_dst)
			ld (hl), 0
			ret

; Exists(name): True / False
rd_exists:
			call rd_find
			ld hl, 0
			ret c
			dec hl
			ret

; Size(name): its length, a Long written at (rd_res) (or a status)
rd_size:
			call rd_find
			ld de, (rd_res)
			jr c, rd_sz_status
			ld hl, rd_ent + 15
			ld bc, 3
			ldir
			xor a
			ld (de), a
			ret
rd_sz_status:
			ex de, hl
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld (hl), #FF
			inc hl
			ld (hl), #FF
			ret

; DirEntry(n): the n-th file's name ("NAME.EXT", 1 = the first) into the
; string at (rd_res); "" past the last (or no disc)
rd_dirent:
			ld hl, (rd_res)
			ld (hl), 0
			dec hl
			ld a, (hl)
			ld (rd_cap), a
			call rd_mount
			ret nz
			ld de, (rd_a1)
			ld a, d
			or a
			ret nz
			ld a, e
			or a
			ret z
			ld b, a
			ld a, (rd_slots)
			push bc
			call rd_sel				; (rd_sel uses BC)
			pop bc
			ld hl, (rd_dir)
rd_de_lp:
			push hl
			ld de, 11
			add hl, de
			bit 7, (hl)
			pop hl
			jr nz, rd_de_done		; past the last
			dec b
			jr z, rd_de_got
			ld de, RD_ENTRY
			add hl, de
			jr rd_de_lp
rd_de_got:
			ld de, rd_name			; (a copy: the ROM goes out before the string is written)
			ld bc, 11
			ldir
			call rd_unsel
			ld hl, rd_name
			ld de, (rd_res)
			ld b, 8
			call rd_de_part
			ld a, (rd_name + 8)
			cp ' '
			jr z, rd_de_end
			ld a, '.'
			call rd_de_put
			ld hl, rd_name + 8
			ld b, 3
			call rd_de_part
rd_de_end:
			xor a
			ld (de), a
			ret
rd_de_done:
			jp rd_unsel
rd_de_part:							; B letters at HL (up to a space) to DE
			ld a, (hl)
			cp ' '
			ret z
			call rd_de_put
			inc hl
			djnz rd_de_part
			ret
rd_de_put:							; A to DE if the string has room
			push af
			ld a, (rd_cap)
			or a
			jr z, rd_dp_full
			dec a
			ld (rd_cap), a
			pop af
			ld (de), a
			inc de
			ret
rd_dp_full:
			pop af
			ret

; SelectVolume("R"): OK when a disc is there, else NotFound
rd_selvol:
			call rd_mount
			ld hl, RD_NOTFOUND
			ret nz
			ld hl, 0
			ret

; rd_ns - NotSupported (a method the disc can't do)
rd_ns:
			ld hl, RD_NOTSUP
			ret

ntc_rg310_e:
			IF ($ < 32768) && (ntc_rg311_e - ntc_rg311 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg311_e - ntc_rg311 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg311:
;## ntc_gfx ntc_data ntc_plat_data @shared @ramonly
; ------------------------------------------------------------
; ntc_gfx - drawing on the CPC screen (Graphics class, Vector3D): lines in
; mode 0, 1 or 2 (ntc_smode), in a pen, XOR (drawing a line again takes it
; off). Two screens for double buffering: #C000 and main RAM's own
; #4000-#7FFF (page 1 - the CRTC always shows main RAM, whatever RAM page the
; Z80 has in the window). Called on the real stack (call / ret); uses IX, IY.
; One loop for every mode: C is a marker of the pixel's bits (mode 0 #AA /
; #55, mode 1 #88 >> n, mode 2 #80 >> n); RRC C moves it one pixel right and
; its carry says "next byte"; the pixel is C and the pen's pattern (IYL).
; ------------------------------------------------------------
gfx_x0:			dw 0
gfx_y0:			dw 0
gfx_x1:			dw 0
gfx_y1:			dw 0
gfx_pen:		db 1
gfx_clip:		db 1			; 1: a line with an end off the screen isn't drawn; 0: no checks
gfx_base:		db #C0			; the screen drawn on (high byte)
gfx_dbl:		db 0			; 1 = double buffering
gfx_shown:		db #30			; CRTC R12 of the screen shown
gfx_sp:			dw 0			; the thread position while a Graphics method works

; gfx_begin / gfx_end - around drawing: main RAM in the window when the
; screen drawn on is #4000, the RAM setting put back after
gfx_begin:
	IF NTC_CPMGFX
			ret						; CP/M: each line does its own (gfx_cpmdraw)
	ENDIF
			ld a, (gfx_base)
			cp #40
			ret nz
			push bc
			ld bc, #7FC0
			out (c), c
			pop bc
			ret
gfx_end:
	IF NTC_CPMGFX
			ret
	ENDIF
			ld a, (gfx_base)
			cp #40
			ret nz
			ld bc, (ntc_rampt)
			out (c), c
			ret

; gfx_width - HL = the screen's width in pixels in this mode
gfx_width:
			ld a, (ntc_smode)
			ld hl, 160
			or a
			ret z
			add hl, hl
			dec a
			ret z
			add hl, hl
			ret

; gfx_line - (gfx_x0, gfx_y0) to (gfx_x1, gfx_y1), pixels of this mode
gfx_line:
			ld a, (gfx_clip)
			or a
			jr z, gfx_l_go
			call gfx_width
			ex de, hl
			ld hl, (gfx_x0)
			call gfx_chk
			ret c
			ld hl, (gfx_x1)
			call gfx_chk
			ret c
			ld de, 200
			ld hl, (gfx_y0)
			call gfx_chk
			ret c
			ld hl, (gfx_y1)
			call gfx_chk
			ret c
gfx_l_go:
			ld hl, (gfx_x1)			; left to right
			ld de, (gfx_x0)
			or a
			sbc hl, de
			jr nc, gfx_l_lr
			ld hl, (gfx_x0)
			ld de, (gfx_x1)
			ld (gfx_x0), de
			ld (gfx_x1), hl
			ld hl, (gfx_y0)
			ld de, (gfx_y1)
			ld (gfx_y0), de
			ld (gfx_y1), hl
			ld hl, (gfx_x1)
			ld de, (gfx_x0)
			or a
			sbc hl, de
gfx_l_lr:
			ld (gfx_dx), hl
			ld hl, (gfx_y1)
			ld de, (gfx_y0)
			or a
			sbc hl, de
			ld a, 0
			jr nc, gfx_l_dy
			call gfx_neg
			ld a, 1
gfx_l_dy:
			ld (gfx_sy), a
			ld (gfx_dy), hl
			call gfx_pat			; IYL = the pen's pattern in this mode
			ld a, (gfx_y0)			; HL = the address of (x0, y0)
			ld c, a
			and #F8
			ld l, a
			ld h, 0
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; (y / 8) * 80
			ld a, c
			and 7
			add a, a
			add a, a
			add a, a
			ld c, a
			ld a, (gfx_base)
			add a, c
			add a, h
			ld h, a
			ld de, (gfx_x0)			; + x / pixels a byte, C = the marker
			ld a, (ntc_smode)
			or a
			jr nz, gfx_l_m12
			ld c, #AA
			srl d
			rr e
			jr nc, gfx_l_adr
			ld c, #55
			jr gfx_l_adr
gfx_l_m12:
			dec a
			ld a, e
			jr nz, gfx_l_m2
			and 3
			ld b, a
			ld c, #88
			srl d
			rr e
			srl d
			rr e
			jr gfx_l_sh
gfx_l_m2:
			and 7
			ld b, a
			ld c, #80
			srl d
			rr e
			srl d
			rr e
			srl d
			rr e
gfx_l_sh:
			ld a, b
			or a
			jr z, gfx_l_adr
gfx_l_shl:
			rrc c
			djnz gfx_l_shl
gfx_l_adr:
			add hl, de
	IF NTC_CPMGFX
			jp gfx_cpmdraw
	ELSE
			call gfx_begin
			call gfx_l_draw
			jp gfx_end
	ENDIF
; >gfxhi - CP/M: the compiler copies from here to <gfxhi into common memory
; (GFH_AT, #C000), labels gfx_ renamed gfh_: the copy CP/M Plus draws with
gfx_dx:			dw 0
gfx_dy:			dw 0
gfx_out:		db 0
gfx_sy:			db 0			; 0 down, 1 up
	IF NTC_CPMGFX
; gfx_go (run as gfh_go, in common memory) - CP/M Plus: draw the line with
; RAM configuration C1 (the screen, block 1, at #4000), on a stack in common
; memory (C1 takes away the program's own #0000-#BFFF), then C2 back
gfx_go:
			ld (gfx_hsp), sp
			ld sp, gfx_hstk
			ld a, i					; P/V = interrupts on: off while C1 is in
			di
			push af
			ld a, c
			ld bc, #7FC1
			out (c), c
			ld c, a
			call gfx_l_draw
			ld bc, #7FC2
			out (c), c
			pop af
			ld sp, (gfx_hsp)
			ret po
			ei
			ret
gfx_hsp:		dw 0
				ds 24
gfx_hstk:
	ENDIF
gfx_l_draw:
			ld a, c					; the first pixel
			and iyl
			xor (hl)
			ld (hl), a
			push hl
			ld hl, (gfx_dx)
			ld de, (gfx_dy)
			or a
			sbc hl, de
			pop hl
			jp c, gfx_ymaj
			ld de, (gfx_dy)			; x major: count dx, error dx / 2, IX = dy
			push de
			pop ix
			ld de, (gfx_dx)
			call gfx_cnt
			ret z
			ld de, (gfx_dx)
			srl d
			rr e
			ld a, (gfx_sy)
			or a
			jp nz, gfx_xu
gfx_xd:
			rrc c					; x + 1
			jr nc, gfx_xd1
			inc hl
gfx_xd1:
			ld a, e					; error - dy
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_xd2
			push hl					; error + dx, y + 1
			ld hl, (gfx_dx)
			add hl, de
			ex de, hl
			pop hl
			ld a, h
			add a, 8
			ld h, a
			and #38
			jr nz, gfx_xd2
			push de
			ld de, #C050
			add hl, de
			pop de
gfx_xd2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_xd
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_xd
			ret
gfx_xu:
			rrc c
			jr nc, gfx_xu1
			inc hl
gfx_xu1:
			ld a, e
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_xu2
			push hl					; error + dx, y - 1
			ld hl, (gfx_dx)
			add hl, de
			ex de, hl
			pop hl
			ld a, h
			sub 8
			ld h, a
			and #38
			cp #38
			jr nz, gfx_xu2
			push de
			ld de, #3FB0
			add hl, de
			pop de
gfx_xu2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_xu
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_xu
			ret
gfx_ymaj:
			ld de, (gfx_dx)			; y major: count dy, error dy / 2, IX = dx
			push de
			pop ix
			ld de, (gfx_dy)
			call gfx_cnt
			ret z
			ld de, (gfx_dy)
			srl d
			rr e
			ld a, (gfx_sy)
			or a
			jp nz, gfx_yu
gfx_yd:
			ld a, h					; y + 1
			add a, 8
			ld h, a
			and #38
			jr nz, gfx_yd1
			push de
			ld de, #C050
			add hl, de
			pop de
gfx_yd1:
			ld a, e					; error - dx
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_yd2
			push hl					; error + dy, x + 1
			ld hl, (gfx_dy)
			add hl, de
			ex de, hl
			pop hl
			rrc c
			jr nc, gfx_yd2
			inc hl
gfx_yd2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_yd
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_yd
			ret
gfx_yu:
			ld a, h					; y - 1
			sub 8
			ld h, a
			and #38
			cp #38
			jr nz, gfx_yu1
			push de
			ld de, #3FB0
			add hl, de
			pop de
gfx_yu1:
			ld a, e
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_yu2
			push hl
			ld hl, (gfx_dy)
			add hl, de
			ex de, hl
			pop hl
			rrc c
			jr nc, gfx_yu2
			inc hl
gfx_yu2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_yu
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_yu
			ret
; DE = a count: B = its low byte (0 = 256), gfx_out = rounds of B; Z when 0
gfx_cnt:
			ld a, d
			or e
			ret z
			ld b, e
			ld a, e
			or a
			jr z, gfx_cn1
			inc d
gfx_cn1:
			ld a, d
			ld (gfx_out), a
			or 1
			ret
; <gfxhi
	IF NTC_CPMGFX
; gfx_cpmdraw - CP/M on an Amstrad CPC, mode 2 (the console's). CP/M 2.2: the
; screen is #C000 of the program's own 64K: drawn there. CP/M Plus: the program
; runs in RAM configuration C2 (blocks 4-7) and the screen is block 1, at #4000
; only in C1 (blocks 0, 1, 2, 7), where nothing of the program but #C000-#FFFF
; (block 7, common) is left: the first line copies the loop to GFH_AT, and
; each line copies its numbers there and draws with the copy (gfh_go)
gfx_cpmdraw:
			ld a, (gfx_cpm)
			or a
			call z, gfx_cpmver
			cp #30
			jp c, gfx_l_draw		; 2.2
			ld a, h					; Plus: the address worked out for #C000 (gfx_base): #4000 in C1
			sub #80
			ld h, a
			push bc
			push hl
			ld hl, gfx_dx
			ld de, gfh_dx
			ld bc, 6
			ldir
			pop hl
			pop bc
			jp gfh_go
; gfx_cpmver - A = gfx_cpm = the CP/M version (BDOS 12: #22, #31); Plus: the
; copy put in common memory, the heap kept below GFH_AT
gfx_cpmver:
			push bc
			push de
			push hl
			push ix
			push iy
			ld a, i					; P/V = interrupts on (BDOS may turn them on)
			push af
			ld c, 12
			call 5
			di
			pop af
			jp po, gfx_cv1
			ei
gfx_cv1:
			pop iy
			pop ix
			ld a, l
			cp #30
			jr c, gfx_cv2
			ld hl, gfh_src
			ld de, GFH_AT
			ld bc, gfh_end - gfh_start
			ldir
			ld hl, GFH_AT
			ld (ntc_cpmtop), hl
			ld a, #31
gfx_cv2:
			ld (gfx_cpm), a
			pop hl
			pop de
			pop bc
			ret
gfx_cpm:		db 0			; the CP/M version, 0 = not looked at yet
	ENDIF
; HL = a coordinate, DE = the limit: carry when HL is not 0 .. DE - 1
gfx_chk:
			bit 7, h
			scf
			ret nz
			or a
			sbc hl, de
			ccf
			ret
gfx_neg:
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
			ret
; gfx_pat - IYL = the pen's bits for this mode (both / all pixels of a byte)
gfx_pat:
			ld a, (gfx_pen)
			ld b, a
			ld a, (ntc_smode)
			or a
			jr z, gfx_pt0
			dec a
			jr z, gfx_pt1
			ld a, b					; mode 2: pen 1 = every bit
			and 1
			jr z, gfx_ptset
			ld a, #FF
			jr gfx_ptset
gfx_pt1:
			xor a					; mode 1: pen bit 0 in the high nibble, bit 1 low
			bit 0, b
			jr z, gfx_pt1b
			or #F0
gfx_pt1b:
			bit 1, b
			jr z, gfx_ptset
			or #0F
			jr gfx_ptset
gfx_pt0:
			xor a					; mode 0: bit 0 -> 7, 1 -> 3, 2 -> 5, 3 -> 1 (and one
			bit 0, b				; to the right for the second pixel)
			jr z, gfx_p01
			or #C0
gfx_p01:
			bit 1, b
			jr z, gfx_p02
			or #0C
gfx_p02:
			bit 2, b
			jr z, gfx_p03
			or #30
gfx_p03:
			bit 3, b
			jr z, gfx_ptset
			or #03
gfx_ptset:
			ld iyl, a
			ret

; gfx_flip - double buffering: wait for the frame flyback, show the screen
; just drawn, draw on the other one from now on
gfx_flip:
			ld a, (gfx_dbl)
			or a
			ret z
			ld b, #F5				; wait for the vertical sync to start
gfx_fw1:
			in a, (c)
			rra
			jr c, gfx_fw1
gfx_fw2:
			in a, (c)
			rra
			jr nc, gfx_fw2
			ld a, (gfx_base)		; show it: CRTC R12 #30 (#C000) / #10 (#4000)
			cp #C0
			ld a, #30
			ld e, #40
			jr z, gfx_fl1
			ld a, #10
			ld e, #C0
gfx_fl1:
			ld (gfx_shown), a
			ld bc, #BC0C
			out (c), c
			inc b
			out (c), a
			ld a, e
			ld (gfx_base), a
			ret

; gfx_double - A = 1: double buffering on (the screen at #C000 copied to
; #4000, which is drawn on first), 0: off (#C000 shown and drawn on)
gfx_double:
	IF NTC_CPMGFX
			ret						; CP/M: one screen
	ENDIF
			or a
			jr z, gfx_dboff
			ld (gfx_dbl), a
			ld a, #C0				; show #C000 now
			call gfx_dshow
			ld bc, #7FC0
			out (c), c
			ld hl, #C000
			ld de, #4000
			ld bc, #4000
			ldir
			ld bc, (ntc_rampt)
			out (c), c
			ld a, #40
			ld (gfx_base), a
			ret
gfx_dboff:
			ld (gfx_dbl), a
			ld a, #C0
			ld (gfx_base), a
gfx_dshow:
			ld a, #30
			ld (gfx_shown), a
			ld bc, #BC0C
			out (c), c
			inc b
			out (c), a
			ret

; gfx_copyrows - A = text rows from the top: copied from #C000 to #4000 (so
; text printed while double buffering shows on both screens)
gfx_copyrows:
	IF NTC_CPMGFX
			ret						; CP/M: one screen
	ENDIF
			or a
			ret z
			ld e, a
			ld bc, #7FC0
			out (c), c
			ld d, 8					; 8 lines a row
			ld hl, #C000
gfx_cr1:
			push hl
			push de
			ld b, 0
			ld c, e					; rows * 80 bytes
			ld a, 80
			ld h, b
			ld l, b
gfx_cr2:
			add hl, bc
			dec a
			jr nz, gfx_cr2
			ld b, h
			ld c, l
			pop de
			pop hl
			push hl
			push de
			push hl
			ld a, h
			sub #80
			ld d, a
			ld e, l
			pop hl
			ldir
			pop de
			pop hl
			ld a, h
			add a, 8
			ld h, a
			dec d
			jr nz, gfx_cr1
			ld bc, (ntc_rampt)
			out (c), c
			ret

ntc_rg311_e:
			IF ($ < 32768) && (ntc_rg312_e - ntc_rg312 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg312_e - ntc_rg312 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg312:
;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

ntc_rg312_e:
			IF ($ < 32768) && (ntc_rg313_e - ntc_rg313 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg313_e - ntc_rg313 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg313:
;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based) - kept here for Tab
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_smode:		db 1			; screen mode (for the Graphics class)
ntc_fwa:		db 0			; ntc_fwcall: A on return
ntc_fwwrap:		db 0			; 1 = the last character made the firmware wrap
ntc_irqset:		db 0			; 1 = the firmware's fast ticker calls ntc_fwevt
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_irqix:		dw 0
NTC_FWBLK	equ #A5F0		; the fast ticker's event block (central 32K, below the firmware)
ntc_fwtop:		dw #A600		; the top of free RAM (#A5F0 with the fast ticker's block)
ntc_fwblk:		dw NTC_FWBLK		; the fast ticker's event block: lower (and the top with it) when the ROMs
								; started take more RAM than AMSDOS's #A700-#ABFF (Option RomEnable)

ntc_rg313_e:
			IF ($ < 32768) && (ntc_rg314_e - ntc_rg314 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg314_e - ntc_rg314 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg314:
;## ntc_plat_fw ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_fwcall - IY = firmware address; A, BC, DE, HL go in and come
; back as the firmware leaves them (A also in ntc_fwa, carry kept).
; IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_fwcall:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call ntc_fwjp
			di
			ld sp, (ntc_ip)
			ld (ntc_fwa), a
			ld ix, (ntc_hostix)
			jp (ix)
ntc_fwjp:
			jp (iy)

ntc_rg314_e:
			IF ($ < 32768) && (ntc_rg315_e - ntc_rg315 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg315_e - ntc_rg315 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg315:
;## ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_putc - A = character: TXT OUTPUT. The firmware wraps by itself after
; the last column, so only the column is counted here; a new line straight after
; that wrap is left out (it would leave an empty line)
ntc_plat_putc:
			ld iy, #BB5A			; TXT OUTPUT
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_fwcall
ntc_pc_back:
			ld ix, (ntc_pclink)
			xor a
			ld (ntc_fwwrap), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr nz, ntc_pc_done
			xor a				; the firmware wrapped to the next line
			ld (ntc_curx), a
			inc a
			ld (ntc_fwwrap), a
ntc_pc_done:
			jp (ix)

; ntc_plat_newline - CR LF (the firmware scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_fwwrap)
			or a
			jr z, ntc_nl_go
			xor a
			ld (ntc_fwwrap), a
			jp (ix)
ntc_nl_go:
			ld (ntc_pclink), ix
			ld a, 13
			ld iy, #BB5A
			ld ix, ntc_nl_lf
			jp ntc_fwcall
ntc_nl_lf:
			ld a, 10
			ld iy, #BB5A
			ld ix, ntc_nl_done
			jp ntc_fwcall
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			ld ix, (ntc_pclink)
			jp (ix)

ntc_pclink:		dw 0

ntc_rg315_e:
			IF ($ < 32768) && (ntc_rg316_e - ntc_rg316 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg316_e - ntc_rg316 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg316:
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_cls - TXT CLEAR WINDOW, cursor home
ntc_plat_cls:
			xor a
			ld (ntc_fwwrap), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			ld iy, #BB6C			; TXT CLEAR WINDOW
			jp ntc_fwcall

ntc_rg316_e:
			IF ($ < 32768) && (ntc_rg317_e - ntc_rg317 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg317_e - ntc_rg317 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg317:
;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_mode - A = mode 0-2 (3 = 2): SCR SET MODE (clears)
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld b, 20
			or a
			jr z, ntc_md_set
			ld b, 40
			cp 1
			jr z, ntc_md_set
			ld b, 80
ntc_md_set:
			ld (ntc_smode), a
			ld c, a
			ld a, b
			ld (ntc_scols), a
			xor a
			ld (ntc_fwwrap), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			ld a, c
			ld iy, #BC0E			; SCR SET MODE
			jp ntc_fwcall

ntc_rg317_e:
			IF ($ < 32768) && (ntc_rg318_e - ntc_rg318 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg318_e - ntc_rg318 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg318:
;## ntc_plat_locate @unit ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_locate - H = column, L = row, 1 based: TXT SET CURSOR
ntc_plat_locate:
			ld a, h
			or a
			jr nz, ntc_lc_x
			inc h
ntc_lc_x:
			ld a, l
			or a
			jr nz, ntc_lc_y
			inc l
ntc_lc_y:
			xor a
			ld (ntc_fwwrap), a
			ld a, h
			dec a
			ld (ntc_curx), a
			ld a, l
			dec a
			ld (ntc_cury), a
			ld iy, #BB75			; TXT SET CURSOR
			jp ntc_fwcall

ntc_rg318_e:
			IF ($ < 32768) && (ntc_rg319_e - ntc_rg319 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg319_e - ntc_rg319 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg319:
;## ntc_plat_key ntc_plat_fw ntc_data
; ntc_plat_scankey - A = key from the firmware's buffer, or 0
ntc_plat_scankey:
			ld (ntc_kslink), ix
			ld iy, #BB09			; KM READ CHAR
			ld ix, ntc_ks_back
			jp ntc_fwcall
ntc_ks_back:
			ld ix, (ntc_kslink)
			jr c, ntc_ks_got
			xor a
			jp (ix)
ntc_ks_got:
			ld a, (ntc_fwa)
			jp (ix)

; ntc_plat_getkey - wait for a key: KM WAIT CHAR
ntc_plat_getkey:
			ld iy, #BB06			; KM WAIT CHAR
			jp ntc_fwcall
ntc_kslink:		dw 0

ntc_rg319_e:
			IF ($ < 32768) && (ntc_rg320_e - ntc_rg320 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg320_e - ntc_rg320 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg320:
;## ntc_plat_ticks ntc_plat_fw
; ntc_plat_ticks - HL = the firmware's 1/300 s clock (KL TIME PLEASE, low word)
ntc_plat_ticks:
			ld iy, #BD0D
			jp ntc_fwcall

ntc_rg320_e:
			IF ($ < 32768) && (ntc_rg321_e - ntc_rg321 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg321_e - ntc_rg321 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg321:
;## ntc_plat_exit ntc_plat_data ntc_plat_fw
ntc_plat_exit:
			ld bc, #7FC0		; RAM setting back to plain (a Memory page may be in #4000)
			out (c), c
			ld a, (ntc_irqset)	; the fast ticker out of the firmware's list
			or a
			jr z, ntc_ex_done
			xor a
			ld (ntc_irqset), a
			ld (ntc_irqix), ix
			ld hl, (ntc_fwblk)
			ld iy, #BCE6		; KL DEL FAST TICKER
			ld ix, ntc_ex_back
			jp ntc_fwcall
ntc_ex_back:
			ld ix, (ntc_irqix)
ntc_ex_done:
			jp (ix)

ntc_rg321_e:
			IF ($ < 32768) && (ntc_rg322_e - ntc_rg322 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg322_e - ntc_rg322 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg322:
;## ntc_plat_fs ntc_data ntc_buf2k @shared
FS_NOTFOUND	equ -2
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_BADNAME	equ -4
fs_a1:			dw 0
fs_a2:			dw 0
fs_a3:			dw 0
fs_res:			dw 0
fs_sp:			dw 0
fs_esp:			dw 0
fs_six:			dw 0
fs_siy:			dw 0
fs_len:			dw 0
fs_nostore:		db 0
fs_hmode:		db 0			; 0 no file open, 1 reading, 2 writing (Open)
fs_init:		db 0			; 1 = checked: is AMSDOS running?
fs_dos:			db 0			; 1 = a DOS is there (|DISC found)
fs_devd:		db 0			; the device in use: 0 tape, 1 disc
fs_n_tape:		db "TAPE", 0
fs_n_disc:		db "DISC", 0
fs_n_all:		db "TAPE,DISC", 0
fs_c_tape:		db "TAP", "E" + #80
fs_c_disc:		db "DIS", "C" + #80
fs_vol:			ds 9			; the volume in use ("" = not known)
fs_vols:		ds 145			; the volumes that worked, "A,C,M" (up to 16 of up to 8 letters)
fs_tmpn:		ds 9			; a volume name, capitals
fs_rsxn:		ds 17			; a command name (last letter + #80), up to 16 letters
			ASSERT NTC_BUFSIZE >= 2048, "FileSystem needs the whole 2K buffer (Option Buffer's size)"
			ASSERT ntc_free <= #A600, "FileSystem on cpcfw: the program and its arrays must end below #A600 (AMSDOS's RAM)"

fs_go0:
			ld a, 1
			ld (fs_nostore), a
			jr fs_gostart
fs_go:
			xor a
			ld (fs_nostore), a
fs_gostart:
			ld (fs_sp), sp
			ld sp, (ntc_csp)
			ld (fs_six), ix
			ld (fs_siy), iy
			ei
			ld (fs_esp), sp
			call fs_jphl
fs_back:
			di
			ld ix, (fs_six)
			ld iy, (fs_siy)
			ld a, (fs_nostore)
			or a
			jr nz, fs_gone
			ex de, hl
			ld hl, (fs_res)
			ld (hl), e
			inc hl
			ld (hl), d
fs_gone:
			ld sp, (fs_sp)
			ret
fs_jphl:
			jp (hl)
fs_err:
			ld sp, (fs_esp)
			jr fs_back

; fs_start - the first file call: is AMSDOS running? (no ROMs are started here:
; Option RomEnable does that in the start code)
fs_start:
			ld a, (fs_init)
			or a
			ret nz
			inc a
			ld (fs_init), a
			ld a, (#BC77)
			cp #DF				; a far call: AMSDOS has the cassette calls
			jr nz, fs_st_find	; not running (RUN" dropped it), or |TAPE: tape
			ld a, 1
			ld (fs_devd), a
		IF NTC_ROMENABLE
			ld hl, fs_n_a1		; started by the program: AMSDOS starts on drive A
			call fs_addvol
			ld hl, fs_n_a1
			ld de, fs_vol
			ld bc, 2
			ldir
		ENDIF
fs_st_find:
			ld hl, fs_c_disc
			call #BCD4			; KL FIND COMMAND: is |DISC there?
			ld a, 1
			jr c, fs_st_dos
			xor a
fs_st_dos:
			ld (fs_dos), a
			ret
fs_n_a1:		db "A", 0

; fs_rsx - HL = an AMSDOS command's name (last letter + #80): run it, no arguments.
; Not there goes to fs_err (NotFound)
fs_rsx:
			call #BCD4			; KL FIND COMMAND: HL = address, C = ROM
			jr nc, fs_rx_none
			xor a				; no arguments
			ld ix, fs_rx_none	; (the argument list: none)
			call #001B			; KL FAR PCALL
			ret
fs_rx_none:
			ld hl, FS_NOTFOUND
			jp fs_err

; fs_strout - HL = text (0 ended) into the String result at (fs_res), cut at its size
fs_strout:
			ex de, hl
			ld hl, (fs_res)
			dec hl
			ld b, (hl)			; the capacity
			inc hl
			ex de, hl
fs_so_lp:
			ld a, (hl)
			or a
			jr z, fs_so_end
			ld c, a
			ld a, b
			or a
			jr z, fs_so_end
			ld a, c
			ld (de), a
			inc hl
			inc de
			dec b
			jr fs_so_lp
fs_so_end:
			xor a
			ld (de), a
			ret

; fs_same - HL = the program's text, DE = a name in capitals: Z when the same (any case)
fs_same:
			ld a, (hl)
			call fs_up
			ld c, a
			ld a, (de)
			cp c
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr fs_same

; fs_volname - HL = text: a volume name (up to 8 letters, a ':' after it is allowed) into
; fs_tmpn (capitals) and fs_rsxn (last letter + #80). NZ: not a name
fs_volname:
			ld de, fs_tmpn
			ld b, 0
fs_vn_lp:
			ld a, (hl)
			or a
			jr z, fs_vn_end
			cp ':'
			jr z, fs_vn_colon
			call fs_up
			ld (de), a
			inc hl
			inc de
			inc b
			ld a, b
			cp 9
			jr c, fs_vn_lp
			or a				; too long: NZ (A = 9)
			ret
fs_vn_colon:
			inc hl
			ld a, (hl)
			or a
			ret nz				; something after the ':'
fs_vn_end:
			xor a
			ld (de), a
			ld a, b
			or a
			jr z, fs_vn_bad
			ld hl, fs_tmpn
			ld de, fs_rsxn
			ld c, b
			ld b, 0
			ldir
			dec de
			ld a, (de)
			or #80
			ld (de), a
			xor a				; Z: a name
			ret
fs_vn_bad:
			inc a				; NZ
			ret

; fs_addvol - HL = a volume name (capitals, 0 ended): into fs_vols if not there and room
fs_addvol:
			ld (fs_len), hl		; (the name)
			ld de, fs_vols
fs_av_entry:
			ld a, (de)
			or a
			jr z, fs_av_add		; the end of the list: not there
			ld hl, (fs_len)
fs_av_cmp:
			ld a, (de)
			cp ','
			jr z, fs_av_sep
			or a
			jr z, fs_av_sep
			cp (hl)
			jr nz, fs_av_skip
			inc hl
			inc de
			jr fs_av_cmp
fs_av_sep:
			ld a, (hl)			; the entry ended: the same if the name ended too
			or a
			ret z
fs_av_skip:
			ld a, (de)			; on to the next entry
			or a
			jr z, fs_av_add
			inc de
			cp ','
			jr nz, fs_av_skip
			jr fs_av_entry
fs_av_add:
			ld hl, (fs_len)		; DE = the 0 at the end: room for "," + name + 0?
			push hl
			ld b, 0
fs_av_len:
			ld a, (hl)
			or a
			jr z, fs_av_room
			inc hl
			inc b
			jr fs_av_len
fs_av_room:
			pop hl
			push hl
			ld hl, fs_vols + 145 - 2
			or a
			sbc hl, de
			ld a, h
			or a
			jr nz, fs_av_ok		; plenty
			ld a, l
			cp b
			jr nc, fs_av_ok
			pop hl
			ret					; full: not added
fs_av_ok:
			pop hl
			ld a, e
			cp low fs_vols
			jr nz, fs_av_comma
			ld a, d
			cp high fs_vols
			jr z, fs_av_copy
fs_av_comma:
			ld a, ','
			ld (de), a
			inc de
fs_av_copy:
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			or a
			jr nz, fs_av_copy
			ret

; fs_namevol - after a Load / Save that worked: a volume in its name ("C:NAME") joins the list
fs_namevol:
			ld hl, (fs_a1)
			ld b, 9
fs_nv_lp:
			ld a, (hl)
			or a
			ret z
			cp ':'
			jr z, fs_nv_found
			inc hl
			djnz fs_nv_lp
			ret
fs_nv_found:
			ld a, 9
			sub b
			ret z				; ":NAME": no volume
			ld hl, (fs_a1)
			ld de, fs_tmpn
			ld c, a
			ld b, 0
fs_nv_cp:
			ld a, (hl)
			call fs_up
			ld (de), a
			inc hl
			inc de
			dec c
			jr nz, fs_nv_cp
			xor a
			ld (de), a
			ld hl, fs_tmpn
			jp fs_addvol

; Devices(): "TAPE,DISC" with a DOS, "TAPE" without
fs_devices:
			call fs_start
			ld hl, fs_n_all
			ld a, (fs_dos)
			or a
			jp nz, fs_strout
			ld hl, fs_n_tape
			jp fs_strout

; CurrentDevice(): "TAPE" or "DISC"
fs_curdev:
			call fs_start
			ld hl, fs_n_tape
			ld a, (fs_devd)
			or a
			jp z, fs_strout
			ld hl, fs_n_disc
			jp fs_strout

; SelectDevice(name): "TAPE" or "DISC" (any case). OK, NotFound
fs_select:
			call fs_start
			ld hl, (fs_a1)
			ld de, fs_n_tape
			call fs_same
			jr z, fs_se_tape
			ld hl, (fs_a1)
			ld de, fs_n_disc
			call fs_same
			jr nz, fs_se_bad
			ld a, (fs_dos)
			or a
			jr z, fs_se_bad		; no DOS: no disc
			ld hl, fs_c_disc
			call fs_rsx
			ld a, 1
			jr fs_se_done
fs_se_tape:
			ld a, (fs_dos)
			or a
			jr z, fs_se_t2		; no DOS: tape anyway
			ld hl, fs_c_tape
			call fs_rsx
fs_se_t2:
			xor a
fs_se_done:
			ld (fs_devd), a
			ld hl, 0
			ret
fs_se_bad:
			ld hl, FS_NOTFOUND
			ret

; Volumes(): the volumes that worked so far ("A,C")
fs_volumes:
			call fs_start
			ld hl, fs_vols
			jp fs_strout

; CurrentVolume(): the volume last selected ("" = not known)
fs_curvol:
			call fs_start
			ld hl, fs_vol
			jp fs_strout

; SelectVolume(name): runs the DOS's command of that name (|A, |B, |C, |M ... whatever
; the DOS has). OK, NotFound (no such command). It joins Volumes()
fs_selvol:
			call fs_start
			ld hl, (fs_a1)
			call fs_volname
			jr nz, fs_se_bad
			ld hl, fs_rsxn
			call fs_rsx
			ld hl, fs_tmpn
			ld de, fs_vol
			ld bc, 9
			ldir
			ld hl, fs_tmpn
			call fs_addvol
			ld hl, 0
			ret

; Command(name): run a ROM's command (an RSX: |NAME) with no arguments - AMSDOS, M4,
; a utility ROM ... OK, NotFound (no ROM has it). Up to 16 letters
fs_command:
			call fs_start
			ld hl, (fs_a1)
			ld de, fs_rsxn
			ld b, 0
fs_cm_lp:
			ld a, (hl)
			or a
			jr z, fs_cm_end
			call fs_up
			ld (de), a
			inc hl
			inc de
			inc b
			ld a, b
			cp 17
			jr c, fs_cm_lp
fs_cm_bad:
			ld hl, FS_NOTFOUND
			ret
fs_cm_end:
			ld a, b
			or a
			jr z, fs_cm_bad
			dec de
			ld a, (de)
			or #80
			ld (de), a
			ld hl, fs_rsxn
			call fs_rsx
			ld hl, 0
			ret

fs_up:
			cp 'a'
			ret c
			cp 'z' + 1
			ret nc
			sub 32
			ret

; fs_name - B = length of the name at (fs_a1), HL = the name; an empty or too long name goes to fs_err
fs_name:
			ld hl, (fs_a1)
			ld b, 0
fs_nm_lp:
			ld a, (hl)
			or a
			jr z, fs_nm_end
			inc hl
			inc b
			ld a, b
			cp 17
			jr c, fs_nm_lp
fs_nm_bad:
			ld hl, FS_BADNAME
			jp fs_err
fs_nm_end:
			ld a, b
			or a
			jr z, fs_nm_bad
			ld hl, (fs_a1)
			ret

; Load(name, addr, maxlen): bytes loaded (the file's length), or a status.
; A file longer than maxlen is not loaded: FS_TOOBIG
fs_load:
			call fs_start
			ld a, (fs_hmode)	; the buffer is the open file's
			or a
			ld hl, FS_FAILED
			jp nz, fs_err
			call fs_name
			ld de, fs_buf
			call #BC77			; CAS IN OPEN: BC = length, carry = ok
			jr c, fs_ld_open
			ld hl, FS_NOTFOUND
			jp fs_err
fs_ld_open:
			ld (fs_len), bc
			ld hl, (fs_a3)
			or a
			sbc hl, bc
			jr nc, fs_ld_fits
			call #BC7D			; CAS IN ABANDON
			ld hl, FS_TOOBIG
			jp fs_err
fs_ld_fits:
			ld hl, (fs_a2)
			call #BC83			; CAS IN DIRECT
			jr c, fs_ld_read
			call #BC7D
			ld hl, FS_FAILED
			jp fs_err
fs_ld_read:
			call #BC7A			; CAS IN CLOSE
			ld hl, (fs_len)
			push hl
			call fs_namevol
			pop hl
			ret

; Save(name, addr, len): a binary file (type 2, BASIC can LOAD it back). 0 or a status
fs_save:
			call fs_start
			ld a, (fs_hmode)	; the buffer is the open file's
			or a
			ld hl, FS_FAILED
			jp nz, fs_err
			call fs_name
			ld de, fs_buf
			call #BC8C			; CAS OUT OPEN
			jr c, fs_sv_open
			ld hl, FS_FAILED
			jp fs_err
fs_sv_open:
			ld hl, (fs_a2)
			ld de, (fs_a3)
			ld bc, 0			; entry address: none
			ld a, 2				; binary
			call #BC98			; CAS OUT DIRECT
			jr c, fs_sv_done
			call #BC92			; CAS OUT ABANDON
			ld hl, FS_FAILED
			jp fs_err
fs_sv_done:
			call #BC8F			; CAS OUT CLOSE
			ld hl, FS_FAILED
			ret nc
			call fs_namevol
			ld hl, 0
			ret

ntc_rg322_e:
			IF ($ < 32768) && (ntc_rg323_e - ntc_rg323 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg323_e - ntc_rg323 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg323:
;## ntc_plat_fsseq ntc_plat_fs @shared
; ---- one open file (handle 1), through CAS IN CHAR / CAS OUT CHAR: read a
; file (any type) byte by byte, or write a new text file (type ASCII, as
; BASIC's OPENOUT / PRINT #9 make it). The 2K buffer is the one Load / Save
; use, so Load and Save are refused while a file is open.
FS_NOHANDLE	equ -5
FS_BADHANDLE	equ -6
FS_EOFST	equ -7
FS_BADMODE	equ -11
FS_NOTSUP	equ -1
fs_ptr:			dw 0
fs_cnt:			db 0
fs_cap:			db 0

; Open(name, mode): 1, or a status. ForUpdate: NotSupported
fs_open:
			call fs_start
			ld a, (fs_hmode)
			or a
			ld hl, FS_NOHANDLE
			ret nz
			ld hl, (fs_a2)
			ld a, h
			or a
			jr nz, fs_op_bad
			ld a, l
			cp 4
			jr z, fs_op_in			; ForReadRaw
			cp 3
			ld hl, FS_NOTSUP
			ret z
			jr nc, fs_op_bad
			cp 1
			jr c, fs_op_bad
			jr nz, fs_op_out
fs_op_in:
			ld (fs_raw), a			; 4: raw (a #1A is data), 1: not
			ld hl, fs_pend
			ld (hl), 0
			call fs_name
			ld de, fs_buf
			call #BC77			; CAS IN OPEN
			ld hl, FS_NOTFOUND
			ret nc
			ld (fs_ftype), a
			ld a, 1
			jr fs_op_ok
fs_op_out:
			call fs_name
			ld de, fs_buf
			call #BC8C			; CAS OUT OPEN
			ld hl, FS_FAILED
			ret nc
			ld a, 2
fs_op_ok:
			ld (fs_hmode), a
			ld hl, 1
			ret
fs_op_bad:
			ld hl, FS_BADMODE
			ret

; fs_hchk - (fs_a1) must be handle 1 open for A (1 read, 2 write), else
; fs_err BadHandle
fs_hchk:
			ld hl, (fs_a1)
			dec hl
			ld b, a
			ld a, h
			or l
			jr nz, fs_hc_bad
			ld a, (fs_hmode)
			cp b
			ret z
fs_hc_bad:
			ld hl, FS_BADHANDLE
			jp fs_err

; Close(h): OK, or a status (Failed: the last of a written file didn't go)
fs_closeh:
			ld hl, (fs_a1)
			dec hl
			ld a, h
			or l
			jr nz, fs_hc_bad
			ld a, (fs_hmode)
			or a
			jr z, fs_hc_bad
			ld b, a
			xor a
			ld (fs_hmode), a
			ld a, b
			cp 1
			jr nz, fs_cl_out
			call #BC7A			; CAS IN CLOSE
			jr fs_cl_ok
fs_cl_out:
			call #BC8F			; CAS OUT CLOSE
			ld hl, FS_FAILED
			ret nc
fs_cl_ok:
			call fs_namevol
			ld hl, 0
			ret

; ReadByte(h): 0-255, or EndOfFile
fs_readb:
			ld a, 1
			call fs_hchk
			call fs_inchar
			ld hl, FS_EOFST
			ret nc
			ld l, a
			ld h, 0
			ret

; WriteByte(h, b): OK, or Failed
fs_writeb:
			ld a, 2
			call fs_hchk
			ld a, (fs_a2)
			call #BC95			; CAS OUT CHAR
			ld hl, FS_FAILED
			ret nc
			ld hl, 0
			ret

; fs_inchar - CAS IN CHAR for ReadByte / Read: in a binary file AMSDOS still reports a #1A
; byte as the soft end of file (no carry, A = #1A) and goes on after it: that is the byte
; #1A. The same in any file opened ForReadRaw (a file with no header: AMSDOS calls it ASCII
; text, but the real end is the hard one, #0F, after the last record). Carry = a byte in A;
; no carry = the end (or an error)
fs_inchar:
			ld a, (fs_pend)
			or a
			jr z, fs_ic_rd
			xor a
			ld (fs_pend), a
			ld a, (fs_pendc)		; the byte Eof read ahead
			scf
			ret
fs_ic_rd:
			call #BC80			; CAS IN CHAR
			ret c
			cp #1A
			jr nz, fs_ic_end
			ld a, (fs_raw)
			cp 4
			ld a, #1A
			scf
			ret z				; raw: the byte #1A
			ld a, (fs_ftype)
			and #0E
			cp 2
			ld a, #1A
			scf
			ret z				; binary: the byte #1A
fs_ic_end:
			or a
			ret
fs_raw:			db 0			; Open for reading: 4 = ForReadRaw
fs_pend:		db 0			; 1: Eof read a byte ahead, in fs_pendc
fs_pendc:		db 0
fs_ftype:		db 0			; Open for reading: the file's type (CAS IN OPEN's A: 2 binary, #16 ASCII)

; Read(h, addr, count): bytes read (fewer at the end)
fs_read:
			ld a, 1
			call fs_hchk
			ld hl, (fs_a2)
			ld de, (fs_a3)
			ld bc, 0
fs_rd_lp:
			ld a, d
			or e
			jr z, fs_rd_end
			bit 7, d
			jr nz, fs_rd_end
			push hl
			push de
			push bc
			call fs_inchar
			pop bc
			pop de
			pop hl
			jr nc, fs_rd_end
			ld (hl), a
			inc hl
			inc bc
			dec de
			jr fs_rd_lp
fs_rd_end:
			ld h, b
			ld l, c
			ret

; Write(h, addr, count): count, or Failed
fs_write:
			ld a, 2
			call fs_hchk
			ld hl, (fs_a2)
			ld de, (fs_a3)
fs_wr_lp:
			ld a, d
			or e
			jr z, fs_wr_end
			bit 7, d
			jr nz, fs_wr_end
			ld a, (hl)
			push hl
			push de
			call #BC95			; CAS OUT CHAR
			pop de
			pop hl
			jr nc, fs_wr_fail
			inc hl
			dec de
			jr fs_wr_lp
fs_wr_end:
			ld hl, (fs_a3)
			ret
fs_wr_fail:
			ld hl, FS_FAILED
			ret

; Eof(h): True (-1) when there is nothing more to read (or h is not a file being read)
fs_eof:
			ld hl, (fs_a1)
			dec hl
			ld a, h
			or l
			jr nz, fs_ef_yes
			ld a, (fs_hmode)
			cp 1
			jr nz, fs_ef_yes
			call fs_inchar			; a byte read ahead (CAS TEST EOF at a #1A - a soft end
			ld hl, -1			; of file - loses bytes: the #1A and more)
			ret nc
			ld (fs_pendc), a
			ld a, 1
			ld (fs_pend), a
			ld hl, 0
			ret
fs_ef_yes:
			ld hl, -1
			ret

; ReadLine(h): the next line (up to LF; CR dropped), "" at the end
fs_readln:
			ld hl, (fs_res)
			ld (hl), 0
			dec hl
			ld a, (hl)
			ld (fs_cap), a			; the result's capacity
			inc hl
			ld (fs_ptr), hl
			xor a
			ld (fs_cnt), a
			ld a, 1
			call fs_hchk
fs_rl_lp:
			call fs_inchar
			jr nc, fs_rl_end
			cp 10
			jr z, fs_rl_end
			cp 13
			jr z, fs_rl_lp
			ld c, a
			ld a, (fs_cap)
			ld hl, fs_cnt
			cp (hl)
			jr z, fs_rl_lp			; full: the rest of the line is dropped
			inc (hl)
			ld hl, (fs_ptr)
			ld (hl), c
			inc hl
			ld (fs_ptr), hl
			jr fs_rl_lp
fs_rl_end:
			ld hl, (fs_ptr)
			ld (hl), 0
			ret

; WriteLine(h, s): the text and CR LF. OK, or Failed
fs_writeln:
			ld a, 2
			call fs_hchk
			ld hl, (fs_a2)
fs_wl_lp:
			ld a, (hl)
			or a
			jr z, fs_wl_end
			push hl
			call #BC95			; CAS OUT CHAR
			pop hl
			jp nc, fs_wr_fail
			inc hl
			jr fs_wl_lp
fs_wl_end:
			ld a, 13
			call #BC95
			jp nc, fs_wr_fail
			ld a, 10
			call #BC95
			jp nc, fs_wr_fail
			ld hl, 0
			ret

ntc_rg323_e:
			IF ($ < 32768) && (ntc_rg324_e - ntc_rg324 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg324_e - ntc_rg324 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg324:
;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: #A600 (the firmware's and AMSDOS's RAM is above), #A5F0 when the fast
; ticker's event block is there (Interrupt, interrupt classes). Called on the
; real stack (call / ret).
ntc_plat_memtop:
			ld hl, (ntc_fwtop)
			ret

ntc_rg324_e:
			IF ($ < 32768) && (ntc_rg325_e - ntc_rg325 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg325_e - ntc_rg325 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg325:
;## ntc_plat_romsel @shared @ramonly
; rd_sel - A = a slot: that ROM in at #C000 (KL ROM SELECT: the upper ROM on,
; the firmware knows). rd_unsel - what was in before back (KL ROM DESELECT).
; From RAM only (@ramonly: never in the keyword ROM). Keep DE, HL (rd_unsel
; also AF)
rd_old:			dw 0
rd_sel:
			push hl
			push de
			ld c, a
			call #B90F			; KL ROM SELECT: B / C = the state and ROM before
			ld (rd_old), bc
			pop de
			pop hl
			ret
rd_unsel:
			push af
			push hl
			push de
			ld bc, (rd_old)
			call #B918			; KL ROM DESELECT
			pop de
			pop hl
			pop af
			ret

ntc_rg325_e:
			IF ($ < 32768) && (ntc_rg326_e - ntc_rg326 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg326_e - ntc_rg326 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg326:
;## ntc_plat_rdroute ntc_plat_fs ntc_romdisc @shared @ramonly
; rd_route ... - a FileSystem method's way to the ROMDISC (volume R): HL =
; the fs_ routine, DE = the rd_ one, fs_a1 ... fs_res set. The rd_ routine
; is picked (fs_a1 .. fs_res copied to rd_a1 .. rd_res) when
;   rd_route / rd_route0:   the name at (fs_a1) is "R:..." - or has no volume
;                           and the volume in use is R
;   rd_routeh / rd_routeh0: fs_a1 is handle 2 (the ROMDISC's open file)
;   rd_routev:              the name is "R" (or "R:")
; then fs_go (the ..0 ones: fs_go0). Runs on the thread: no call, no push.
rd_rtf:			db 0
rd_rtd:			dw 0
rd_routev:
			ld a, 4
			jr rd_rt
rd_routeh0:
			ld a, 3
			jr rd_rt
rd_routeh:
			ld a, 2
			jr rd_rt
rd_route0:
			ld a, 1
			jr rd_rt
rd_route:
			xor a
rd_rt:
			ld (rd_rtf), a
			ld (rd_rtd), de
			bit 1, a
			jr nz, rd_rt_h
			bit 2, a
			jr nz, rd_rt_v
			ex de, hl				; DE = the fs_ routine
			ld hl, (fs_a1)
			inc hl
			ld a, (hl)
			dec hl
			cp ':'
			jr nz, rd_rt_cur
			ld a, (hl)
			or #20
			cp 'r'
			jr z, rd_rt_rd
			jr rd_rt_fs
rd_rt_cur:							; no volume in the name: the one in use
			ld a, (fs_vol)
			cp 'R'
			jr nz, rd_rt_fs
			ld a, (fs_vol + 1)
			or a
			jr z, rd_rt_rd
rd_rt_fs:
			ex de, hl				; HL = the fs_ routine
			jr rd_rt_go
rd_rt_h:
			ex de, hl
			ld hl, (fs_a1)
			ld a, h
			or a
			jr nz, rd_rt_fs
			ld a, l
			cp 2
			jr z, rd_rt_rd
			jr rd_rt_fs
rd_rt_v:
			ex de, hl
			ld hl, (fs_a1)
			ld a, (hl)
			or #20
			cp 'r'
			jr nz, rd_rt_fs
			inc hl
			ld a, (hl)
			or a
			jr z, rd_rt_rd
			cp ':'
			jr nz, rd_rt_fs
			inc hl
			ld a, (hl)
			or a
			jr nz, rd_rt_fs
rd_rt_rd:
			ld hl, (fs_a1)
			ld (rd_a1), hl
			ld hl, (fs_a2)
			ld (rd_a2), hl
			ld hl, (fs_a3)
			ld (rd_a3), hl
			ld hl, (fs_res)
			ld (rd_res), hl
			ld hl, (rd_rtd)
rd_rt_go:
			ld a, (rd_rtf)
			rra
			jp c, fs_go0
			jp fs_go

; rd_fsvol - SelectVolume "R": the disc there, then R is the volume in use
; (names without one go to the disc) and joins Volumes()
rd_fsvol:
			call rd_selvol
			ld a, h
			or l
			ret nz
			ld hl, rd_vr
			ld de, fs_vol
			ld bc, 2
			ldir
			ld hl, rd_vr
			call fs_addvol
			ld hl, 0
			ret
rd_vr:			db "R", 0

; rd_nsl - NotSupported as a Long at (fs_res) (Size on a volume that can't)
rd_nsl:
			ld hl, (fs_res)
			ld a, #FF
			ld (hl), a
			inc hl
			ld (hl), a
			inc hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

ntc_rg326_e:
			IF ($ < 32768) && (ntc_rg327_e - ntc_rg327 + $ > 16384)	; fwdref-ok
			ds 32768 - $		; Option Reserve #4000-#7FFF: round it
			ENDIF
			IF ($ < 41712) && (ntc_rg327_e - ntc_rg327 + $ > 36688)	; fwdref-ok
			ds 41712 - $		; Option Reserve #8F50-#A2EF: round it
			ENDIF
ntc_rg327:
;## ntc_plat_rmr ntc_plat_data
; ntc_plat_rmr - A = the gate array's ROM / mode byte now: the firmware keeps
; it in C' (B' = #7F), so Memory's CallBank can turn both ROMs off and put
; them back. Keeps BC, DE, HL.
ntc_plat_rmr:
			exx
			ld a, c
			exx
			ret


ntc_rg327_e:
ntc_end:				; the end of the program (and of its file)
fs_buf			equ ntc_buf		; the 2K buffer CAS IN OPEN / CAS OUT OPEN want (shared with Memory.Copy)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
			IF (ntc_bssfrom < 32768) && (ntc_bssfrom + ntc_bss_size > 16384)	; fwdref-ok
ntc_bss		equ 32768		; after Option Reserve #4000-#7FFF
			ELSEIF (ntc_bssfrom < 41712) && (ntc_bssfrom + ntc_bss_size > 36688)	; fwdref-ok
ntc_bss		equ 41712		; after Option Reserve #8F50-#A2EF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
arr_vx		equ ntc_bss + 0		; 20 bytes
arr_vz		equ ntc_bss + 20		; 20 bytes
arr_vh		equ ntc_bss + 40		; 20 bytes
arr_vfx		equ ntc_bss + 60		; 20 bytes
arr_vfz		equ ntc_bss + 80		; 20 bytes
arr_vn		equ ntc_bss + 100		; 230 bytes
arr_s3d_bas		equ ntc_bss + 330		; 18 bytes
arr_s3d_pg		equ ntc_bss + 348		; 512 bytes
ntc_bss_size	equ 860
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			IF ntc_free <= 32768	; fwdref-ok
ntc_memtab	equ 32768		; the Memory class's tables: above the window (Option Reserve)
			ELSE
ntc_memtab	equ ntc_free
			ENDIF
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 16384) || (ntc_bss >= 32768), "the program (or its arrays) reaches into Option Reserve #4000-#7FFF (Main.bas line 18)"
			ASSERT (ntc_free <= 36688) || (ntc_bss >= 41712), "the program (or its arrays) reaches into Option Reserve #8F50-#A2EF (Main.bas line 19)"
			ASSERT (ntc_free <= 36688) || (ntc_bss >= 38736), "the program (or its arrays) reaches into Option Reserve #8F50-#974F (Main.bas line 20)"
			SAVEAMSDOS "AUCKLAND.BIN", ntc_start, ntc_end - ntc_start, ntc_start
